const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\nSTYLE\n::cue(.styledotdefault) { background-color:transparent }\n\n9901803\n00:00:26.369 --> 00:00:28.449 align:middle line:85%,start position:50%,middle\nGitHub：rexchen1803\n\nsrc-1\n00:00:28.529 --> 00:00:32.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 可以请您在这儿签名吗？\n- 好的，给您</c>\n\nsrc-2\n00:00:38.830 --> 00:00:40.249 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有文件</c>\n\nsrc-3\n00:00:55.288 --> 00:00:57.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>差不多一半婚姻以离婚收场</c>\n\nsrc-4\n00:00:57.498 --> 00:00:59.977 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但结婚的人一心以为白头到老</c>\n\nsrc-5\n00:01:00.060 --> 00:01:01.103 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>离婚申请书</c>\n\nsrc-6\n00:01:02.919 --> 00:01:04.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉</c>\n\nsrc-7\n00:01:04.630 --> 00:01:07.025 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>麦片公司委托我们宣传……</c>\n\nsrc-8\n00:01:07.109 --> 00:01:09.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你必定非常高兴</c>\n\nsrc-9\n00:01:10.529 --> 00:01:13.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但人生难料</c>\n\nsrc-10\n00:01:13.490 --> 00:01:15.868 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我又怎料到会任职广告公司……</c>\n\nsrc-11\n00:01:15.951 --> 00:01:20.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天天哄小孩吃“脆谷乐”早餐</c>\n\nsrc-12\n00:01:21.665 --> 00:01:24.376 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>逢星期二、五，我最开心</c>\n\nsrc-13\n00:01:24.459 --> 00:01:29.006 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>提早下班，接女儿玛雅下课</c>\n\nsrc-14\n00:01:29.089 --> 00:01:32.426 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>边走边听歌，音乐配合应景……\n心情特别畅快</c>\n\nsrc-15\n00:01:32.509 --> 00:01:36.763 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这一首应该合听</c>\n\nsrc-16\n00:01:37.598 --> 00:01:39.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>臭娘们，亲我的屁股吧……</c>\n\nsrc-17\n00:01:40.165 --> 00:01:42.292 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>另一首才对</c>\n\nsrc-18\n00:02:04.917 --> 00:02:08.086 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>东51街</c>\n\nsrc-19\n00:02:20.829 --> 00:02:23.707 align:middle line:85%,start position:50%,middle\n麦迪逊道\n\nsrc-20\n00:02:29.983 --> 00:02:31.465 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-21\n00:02:32.341 --> 00:02:33.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不用客气</c>\n\nsrc-22\n00:02:48.794 --> 00:02:55.717 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>流落异星！太空船待修！\n手紧待援！</c>\n\nsrc-23\n00:02:58.595 --> 00:03:01.598 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>谢谢！</c>\n\nsrc-24\n00:03:57.112 --> 00:04:00.887 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>但有时无论怎样小心选歌……</c>\n\nsrc-25\n00:04:00.970 --> 00:04:04.431 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>总没有一首配合突发事情</c>\n\nsrc-26\n00:04:12.356 --> 00:04:13.795 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么</c>\n\nsrc-27\n00:04:13.879 --> 00:04:16.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天上性教育课</c>\n\nsrc-28\n00:04:16.423 --> 00:04:17.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>年纪那样小就上？</c>\n\nsrc-29\n00:04:17.632 --> 00:04:20.469 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 离谱\n- 可以鼓励阅读</c>\n\nsrc-30\n00:04:20.552 --> 00:04:21.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有课本！</c>\n\nsrc-31\n00:04:21.928 --> 00:04:25.432 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『射出的精子达2亿5千万颗』</c>\n\nsrc-32\n00:04:25.516 --> 00:04:29.228 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『向输卵管游去』</c>\n\nsrc-33\n00:04:29.311 --> 00:04:30.896 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『1亿颗途中遭消灭……』</c>\n\nsrc-34\n00:04:30.979 --> 00:04:32.439 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要找玛雅去</c>\n\nsrc-35\n00:04:32.459 --> 00:04:33.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你跟爸爸发生性行为？</c>\n\nsrc-36\n00:04:33.961 --> 00:04:35.192 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有没有？</c>\n\nsrc-37\n00:04:35.275 --> 00:04:36.944 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有！</c>\n\nsrc-38\n00:04:37.339 --> 00:04:39.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>憎死你，憎死你呀！</c>\n\nsrc-39\n00:04:45.744 --> 00:04:47.079 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们要谈谈</c>\n\nsrc-40\n00:04:47.955 --> 00:04:51.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>男人把阳具拔出来……</c>\n\nsrc-41\n00:04:51.208 --> 00:04:52.459 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>刺入女人的阴道……</c>\n\nsrc-42\n00:04:52.543 --> 00:04:56.108 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老师没有说『刺入』吧？</c>\n\nsrc-43\n00:04:56.524 --> 00:04:58.025 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有</c>\n\nsrc-44\n00:04:58.590 --> 00:04:59.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不明白</c>\n\nsrc-45\n00:04:59.800 --> 00:05:02.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>小森说他是个意外</c>\n\nsrc-46\n00:05:02.719 --> 00:05:06.682 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎会把阳具意外刺入……路易</c>\n\nsrc-47\n00:05:06.765 --> 00:05:08.494 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎会……</c>\n\nsrc-48\n00:05:08.536 --> 00:05:13.105 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要总说“阴茎”和“刺入”……\n说“小丁丁”、“嘘嘘的地方”吧</c>\n\nsrc-49\n00:05:13.188 --> 00:05:14.314 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用点可爱的词汇</c>\n\nsrc-50\n00:05:14.398 --> 00:05:17.693 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为什么小森是意外\n- 说来复杂</c>\n\nsrc-51\n00:05:18.986 --> 00:05:21.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 阳具！阳具！\n- 细声</c>\n\nsrc-52\n00:05:23.699 --> 00:05:27.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是踩中蕉皮那种意外</c>\n\nsrc-53\n00:05:27.096 --> 00:05:31.248 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是无意中令森妈怀孕的意外</c>\n\nsrc-54\n00:05:32.624 --> 00:05:36.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果他们不想要宝宝，为什么还要做爱？</c>\n\nsrc-55\n00:05:37.462 --> 00:05:39.609 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>问得好</c>\n\nsrc-56\n00:05:40.090 --> 00:05:43.260 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当他们在操练吧</c>\n\nsrc-57\n00:05:45.179 --> 00:05:46.763 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我是意外吗？\n- 不是</c>\n\nsrc-58\n00:05:46.847 --> 00:05:49.099 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我是吧？\n- 不是</c>\n\nsrc-59\n00:05:49.183 --> 00:05:54.021 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我特意制造你出来</c>\n\nsrc-60\n00:05:55.856 --> 00:05:57.399 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『易碎』</c>\n\nsrc-61\n00:05:57.482 --> 00:06:00.027 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你同我妈的经过是怎样？</c>\n\nsrc-62\n00:06:00.110 --> 00:06:03.715 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么『我妈』？好像同我无关</c>\n\nsrc-63\n00:06:04.114 --> 00:06:08.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为你们要离婚了……</c>\n\nsrc-64\n00:06:09.077 --> 00:06:11.330 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是我的，不是你的</c>\n\nsrc-65\n00:06:11.413 --> 00:06:13.540 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是吗？\n- 故事是怎样？</c>\n\nsrc-66\n00:06:13.624 --> 00:06:18.629 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真实的故事，不是……\n『我俩相识！然后相爱！』</c>\n\nsrc-67\n00:06:18.712 --> 00:06:21.131 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『因为相爱……』</c>\n\nsrc-68\n00:06:21.215 --> 00:06:24.510 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『于是组织家庭，制造你出来』</c>\n\nsrc-69\n00:06:24.593 --> 00:06:28.055 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真实的故事，将来才告诉你</c>\n\nsrc-70\n00:06:28.138 --> 00:06:30.057 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 当我长大\n- 对</c>\n\nsrc-71\n00:06:30.140 --> 00:06:33.185 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我知道爱情不是神话\n- 是吗？</c>\n\nsrc-72\n00:06:36.021 --> 00:06:39.274 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你认识她之前，拍过拖？</c>\n\nsrc-73\n00:06:39.358 --> 00:06:41.485 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>从实招来</c>\n\nsrc-74\n00:06:42.653 --> 00:06:44.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>认真拍过两次</c>\n\nsrc-75\n00:06:44.321 --> 00:06:47.741 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还有过几次短暂交往</c>\n\nsrc-76\n00:06:50.911 --> 00:06:53.138 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>男人版的“荡妇”叫什么？</c>\n\nsrc-77\n00:06:53.622 --> 00:06:57.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还没有</c>\n\nsrc-78\n00:06:57.101 --> 00:06:58.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你这星期吃素？</c>\n\nsrc-79\n00:06:58.544 --> 00:07:00.128 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是</c>\n\nsrc-80\n00:07:00.212 --> 00:07:02.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你大概不是她第一个男友</c>\n\nsrc-81\n00:07:02.631 --> 00:07:05.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她之前也许交过一个书呆子，也许那人很刻薄</c>\n\nsrc-82\n00:07:07.027 --> 00:07:08.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>又或者……</c>\n\nsrc-83\n00:07:09.847 --> 00:07:12.015 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也许你们做了很久的朋友，后来……</c>\n\nsrc-84\n00:07:12.099 --> 00:07:16.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你正要把阳具放进其他阴道……</c>\n\nsrc-85\n00:07:16.687 --> 00:07:17.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>晚安</c>\n\nsrc-86\n00:07:17.771 --> 00:07:19.189 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>才察觉妈妈是真命天女！</c>\n\nsrc-87\n00:07:19.206 --> 00:07:20.332 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该上床了！</c>\n\nsrc-88\n00:07:20.416 --> 00:07:23.277 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你为什么爱上她？我想知道</c>\n\nsrc-89\n00:07:23.360 --> 00:07:26.672 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为她聪明、漂亮又风趣</c>\n\nsrc-90\n00:07:26.714 --> 00:07:29.992 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在她又蠢又丑又沉闷？</c>\n\nsrc-91\n00:07:30.075 --> 00:07:32.244 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 当然不是\n- 那还有什么问题？</c>\n\nsrc-92\n00:07:32.327 --> 00:07:36.623 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 说来复杂\n- 你什么都是复杂</c>\n\nsrc-93\n00:07:36.707 --> 00:07:41.753 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说出来，会发觉不复杂</c>\n\nsrc-94\n00:07:41.837 --> 00:07:44.298 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会发觉你还是……爱她</c>\n\nsrc-95\n00:07:45.007 --> 00:07:47.384 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们离婚，我明白你难过</c>\n\nsrc-96\n00:07:47.467 --> 00:07:51.305 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但把故事说出来，于事无补</c>\n\nsrc-97\n00:07:51.388 --> 00:07:55.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者无补，或者有补，说过才知</c>\n\nsrc-98\n00:07:56.226 --> 00:07:59.646 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别再问长问短，应该睡觉</c>\n\nsrc-99\n00:07:59.730 --> 00:08:03.775 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不应该睡觉！\n应该把故事说出来！</c>\n\nsrc-100\n00:08:04.500 --> 00:08:06.111 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想知道！</c>\n\nsrc-101\n00:08:08.280 --> 00:08:09.865 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想知道</c>\n\nsrc-102\n00:08:11.992 --> 00:08:13.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好！</c>\n\nsrc-103\n00:08:14.010 --> 00:08:15.245 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说就说</c>\n\nsrc-104\n00:08:15.329 --> 00:08:16.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但不说出你妈是谁</c>\n\nsrc-105\n00:08:16.747 --> 00:08:18.014 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你自己去猜</c>\n\nsrc-106\n00:08:18.056 --> 00:08:19.458 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\nsrc-107\n00:08:19.541 --> 00:08:21.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会把人物改名换姓</c>\n\nsrc-108\n00:08:21.960 --> 00:08:25.214 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 考考你\n- 神秘爱情故事</c>\n\nsrc-109\n00:08:25.297 --> 00:08:27.466 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 准备好？\n- 未</c>\n\nsrc-110\n00:08:31.345 --> 00:08:33.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 慢慢来\n- 我会</c>\n\nsrc-111\n00:08:33.138 --> 00:08:35.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知你会</c>\n\nsrc-112\n00:08:35.557 --> 00:08:37.601 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 公主枕头？\n- 谢谢</c>\n\nsrc-113\n00:08:47.236 --> 00:08:48.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以开始</c>\n\nsrc-114\n00:08:48.904 --> 00:08:50.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>话说从前……</c>\n\nsrc-115\n00:08:51.281 --> 00:08:55.369 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>电邮、手机、真人骚未出现之前……</c>\n\nsrc-116\n00:08:55.452 --> 00:08:56.537 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>民主党年轻党员</c>\n\nsrc-117\n00:08:56.620 --> 00:09:01.375 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>1992年，威斯康辛州麦迪逊镇……</c>\n\nsrc-118\n00:09:01.458 --> 00:09:04.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有个叫威廉 希斯的小伙子</c>\n\nsrc-119\n00:09:04.127 --> 00:09:07.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 新年快乐，威廉\n- 新年快乐</c>\n\nsrc-120\n00:09:07.798 --> 00:09:13.011 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他深深爱着从大学时代就认识的女友</c>\n\nsrc-121\n00:09:13.095 --> 00:09:14.179 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那就叫吧……</c>\n\nsrc-122\n00:09:14.263 --> 00:09:16.056 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 艾美莉！\n- 艾美莉！</c>\n\nsrc-123\n00:09:20.269 --> 00:09:23.272 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>10……9……8……</c>\n\nsrc-124\n00:09:23.355 --> 00:09:28.443 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>4秒后，谁是世上……\n最幸运的男人？</c>\n\nsrc-125\n00:09:28.527 --> 00:09:29.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你</c>\n\nsrc-126\n00:09:31.655 --> 00:09:33.574 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>新年快乐！</c>\n\nsrc-127\n00:09:33.657 --> 00:09:35.576 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>两人非常登对，不过……</c>\n\nsrc-128\n00:09:35.659 --> 00:09:40.706 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他后来怎娶了你妈呢？</c>\n\nsrc-129\n00:09:40.789 --> 00:09:45.586 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那可得从他那个白日大梦说起</c>\n\nsrc-130\n00:09:45.669 --> 00:09:47.087 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>起立</c>\n\nsrc-131\n00:09:48.797 --> 00:09:53.093 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>恭迎美利坚合众国总统……</c>\n\nsrc-132\n00:09:54.011 --> 00:09:55.846 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉……</c>\n\nsrc-133\n00:09:55.860 --> 00:09:57.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>马修……</c>\n\nsrc-134\n00:09:58.265 --> 00:09:59.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希斯</c>\n\nsrc-135\n00:10:04.062 --> 00:10:06.023 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你想做总统？</c>\n\nsrc-136\n00:10:06.106 --> 00:10:11.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么去纽约替克林顿助选？</c>\n\nsrc-137\n00:10:11.361 --> 00:10:13.447 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纽约助选团需要我</c>\n\nsrc-138\n00:10:13.530 --> 00:10:17.868 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你让威廉去纽约，必会后悔</c>\n\nsrc-139\n00:10:17.951 --> 00:10:22.206 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纽约女孩不仅火辣，而且很放得开</c>\n\nsrc-140\n00:10:22.289 --> 00:10:24.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>难道你不知道？</c>\n\nsrc-141\n00:10:24.625 --> 00:10:26.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 查理说对了怎办？\n- 不用理会</c>\n\nsrc-142\n00:10:26.723 --> 00:10:30.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他有智障\n- 我担心你去纽约会变</c>\n\nsrc-143\n00:10:30.839 --> 00:10:32.841 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 变是好事\n- 我们一起变的话</c>\n\nsrc-144\n00:10:32.925 --> 00:10:35.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那就一起变吧</c>\n\nsrc-145\n00:10:35.719 --> 00:10:38.722 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去两个月就回来</c>\n\nsrc-146\n00:10:38.805 --> 00:10:39.973 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实现我们计划</c>\n\nsrc-147\n00:10:40.057 --> 00:10:43.477 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你竟然放心撇下艾美莉</c>\n\nsrc-148\n00:10:43.560 --> 00:10:47.606 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一直对她流口水</c>\n\nsrc-149\n00:10:48.273 --> 00:10:50.442 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而且我这份人不择手段</c>\n\nsrc-150\n00:10:53.166 --> 00:10:56.711 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>替我交给阿夏</c>\n\nsrc-151\n00:10:57.115 --> 00:10:59.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我希望你结识她\n- 叫阿夏？</c>\n\nsrc-152\n00:10:59.409 --> 00:11:00.661 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是</c>\n\nsrc-153\n00:11:00.744 --> 00:11:02.454 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在剑桥结识，男人见到她……</c>\n\nsrc-154\n00:11:02.538 --> 00:11:05.832 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家都会动心，你也一样</c>\n\nsrc-155\n00:11:05.916 --> 00:11:08.293 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者应该寄给她</c>\n\nsrc-156\n00:11:08.377 --> 00:11:09.336 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是什么？</c>\n\nsrc-157\n00:11:09.419 --> 00:11:12.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一件早该寄给她的东西</c>\n\nsrc-158\n00:11:13.799 --> 00:11:15.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱你，威廉 希斯</c>\n\nsrc-159\n00:11:17.386 --> 00:11:20.973 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去吧，去施展你才华</c>\n\nsrc-160\n00:11:22.224 --> 00:11:24.643 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉似乎是个好妈妈……</c>\n\nsrc-161\n00:11:24.726 --> 00:11:27.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 但未必是我妈\n- 为什么？</c>\n\nsrc-162\n00:11:27.771 --> 00:11:31.859 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先出场必定先被撇</c>\n\nsrc-163\n00:11:31.870 --> 00:11:35.195 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者阿夏是我妈</c>\n\nsrc-164\n00:11:52.045 --> 00:11:53.672 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那一天最难忘</c>\n\nsrc-165\n00:11:53.755 --> 00:11:57.593 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去一向想去的城市</c>\n\nsrc-166\n00:11:57.676 --> 00:12:00.804 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>参与一心想参与的助选</c>\n\nsrc-167\n00:12:00.888 --> 00:12:04.391 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我胸有成竹，以为助选经理……</c>\n\nsrc-168\n00:12:04.474 --> 00:12:07.394 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>慧眼识英雄，一见就知我是人才</c>\n\nsrc-169\n00:12:07.477 --> 00:12:08.979 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后我会写演词</c>\n\nsrc-170\n00:12:09.062 --> 00:12:11.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不久……</c>\n\nsrc-171\n00:12:11.273 --> 00:12:12.649 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯？</c>\n\nsrc-172\n00:12:12.733 --> 00:12:14.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 加拉夫\n- 你是加拉夫</c>\n\nsrc-173\n00:12:14.484 --> 00:12:17.070 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好，一起走</c>\n\nsrc-174\n00:12:17.154 --> 00:12:21.408 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有履历、几份替议员写的演词</c>\n\nsrc-175\n00:12:21.491 --> 00:12:25.454 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我闲来无事，必定会拜读</c>\n\nsrc-176\n00:12:25.537 --> 00:12:30.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>暂时，我要人买咖啡面包</c>\n\nsrc-177\n00:12:30.470 --> 00:12:32.055 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等一等！</c>\n\nsrc-178\n00:12:32.138 --> 00:12:33.431 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要我买咖啡？</c>\n\nsrc-179\n00:12:33.473 --> 00:12:36.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>人人都买过咖啡，现在你买</c>\n\nsrc-180\n00:12:36.673 --> 00:12:37.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很忙</c>\n\nsrc-181\n00:12:37.841 --> 00:12:40.469 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>十点前买来，否则阿瑟要我命</c>\n\nsrc-182\n00:12:40.552 --> 00:12:44.817 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要你赔命，我曾经死过翻生</c>\n\nsrc-183\n00:12:45.485 --> 00:12:46.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是什么吗？</c>\n\nsrc-184\n00:12:46.683 --> 00:12:48.268 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>叫大哥大电话</c>\n\nsrc-185\n00:12:48.352 --> 00:12:51.605 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要你随传随到</c>\n\nsrc-186\n00:12:51.688 --> 00:12:53.868 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿司匹林</c>\n\nsrc-187\n00:12:54.858 --> 00:12:56.985 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>欢迎你加入！</c>\n\nsrc-188\n00:13:00.250 --> 00:13:02.282 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好\n- 什么？你好</c>\n\nsrc-189\n00:13:02.366 --> 00:13:05.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>四星期后，纽约州选民将会……</c>\n\nsrc-190\n00:13:05.337 --> 00:13:09.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>选出民主党的总统候选人</c>\n\nsrc-191\n00:13:09.248 --> 00:13:11.375 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿当选的话……</c>\n\nsrc-192\n00:13:11.875 --> 00:13:14.795 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这里每一个人……</c>\n\nsrc-193\n00:13:14.878 --> 00:13:18.882 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>都是功不可没</c>\n\nsrc-194\n00:13:19.383 --> 00:13:21.311 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>事实如此</c>\n\nsrc-195\n00:13:21.353 --> 00:13:24.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>由此可见，你们肩负重任</c>\n\nsrc-196\n00:13:24.304 --> 00:13:27.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们每一个人……</c>\n\nsrc-197\n00:13:30.279 --> 00:13:32.781 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在这里做什么？</c>\n\nsrc-198\n00:13:33.230 --> 00:13:34.982 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>新丁</c>\n\nsrc-199\n00:13:37.369 --> 00:13:39.862 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>厕纸佬</c>\n\nsrc-200\n00:13:43.282 --> 00:13:47.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 一包红牌，麻烦你\n- $3.25</c>\n\nsrc-201\n00:13:47.828 --> 00:13:51.790 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威斯康辛州麦迪逊镇卖$2.15</c>\n\nsrc-202\n00:13:51.874 --> 00:13:53.208 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那就回去麦迪逊吧</c>\n\nsrc-203\n00:13:53.292 --> 00:13:55.794 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不要忘记来信\n- 对，不要忘记</c>\n\nsrc-204\n00:13:55.878 --> 00:13:58.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>停！</c>\n\nsrc-205\n00:13:58.589 --> 00:14:00.007 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你抽烟？</c>\n\nsrc-206\n00:14:00.090 --> 00:14:01.550 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是……是</c>\n\nsrc-207\n00:14:02.509 --> 00:14:05.470 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不是故意说出来</c>\n\nsrc-208\n00:14:06.805 --> 00:14:12.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我年轻不更事\n现在已经戒了好多年</c>\n\nsrc-209\n00:14:12.570 --> 00:14:15.772 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还有没有应该告诉我的事？</c>\n\nsrc-210\n00:14:16.356 --> 00:14:18.275 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者有……没有</c>\n\nsrc-211\n00:14:24.239 --> 00:14:26.533 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 十份副本\n- 放在那处</c>\n\nsrc-212\n00:14:26.617 --> 00:14:31.705 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿瑟急要</c>\n\nsrc-213\n00:14:31.788 --> 00:14:33.332 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是厕纸佬</c>\n\nsrc-214\n00:14:33.415 --> 00:14:36.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 等一等，她是谁？\n- 爱珮</c>\n\nsrc-215\n00:14:37.669 --> 00:14:40.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对，我是厕纸佬</c>\n\nsrc-216\n00:14:40.797 --> 00:14:42.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也是面包咖啡佬</c>\n\nsrc-217\n00:14:42.674 --> 00:14:47.679 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你尽管叫我“贝果咖啡小弟”</c>\n\nsrc-218\n00:14:47.763 --> 00:14:50.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 几多份？\n- 十份，麻烦你</c>\n\nsrc-219\n00:14:50.849 --> 00:14:53.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这些？\n- 对</c>\n\nsrc-220\n00:14:54.436 --> 00:14:56.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么支持克林顿？</c>\n\nsrc-221\n00:14:56.488 --> 00:14:59.149 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不支持，我打散工，时薪$12</c>\n\nsrc-222\n00:14:59.233 --> 00:15:03.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总比当临时保姆强，我很会带孩子</c>\n\nsrc-223\n00:15:03.612 --> 00:15:05.072 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是民主党党员吧？</c>\n\nsrc-224\n00:15:05.155 --> 00:15:09.785 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不是民主就是共和？</c>\n\nsrc-225\n00:15:09.868 --> 00:15:12.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是独立选民？</c>\n\nsrc-226\n00:15:12.287 --> 00:15:15.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么都不是，为什么要有党派？</c>\n\nsrc-227\n00:15:15.666 --> 00:15:18.919 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么凡事要有立场？</c>\n\nsrc-228\n00:15:19.002 --> 00:15:23.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我怎晓得导弹、社保、税法？</c>\n\nsrc-229\n00:15:23.348 --> 00:15:26.552 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>民权呢？女权呢？</c>\n\nsrc-230\n00:15:26.635 --> 00:15:28.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>女人处理自己身体的自由呢？</c>\n\nsrc-231\n00:15:29.012 --> 00:15:31.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我已经很自由处理自己身体</c>\n\nsrc-232\n00:15:31.557 --> 00:15:33.851 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你即是……事不关己，己不劳心</c>\n\nsrc-233\n00:15:33.934 --> 00:15:35.686 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不是\n- 是</c>\n\nsrc-234\n00:15:35.769 --> 00:15:39.114 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你所效力的这些蠢蛋……</c>\n\nsrc-235\n00:15:39.155 --> 00:15:41.241 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们只为自己野心打算</c>\n\nsrc-236\n00:15:41.324 --> 00:15:42.492 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不对</c>\n\nsrc-237\n00:15:42.534 --> 00:15:44.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你以为克林顿会有作为？</c>\n\nsrc-238\n00:15:44.778 --> 00:15:46.989 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对\n- 他是墙头草</c>\n\nsrc-239\n00:15:47.072 --> 00:15:49.157 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 错\n- 要不要我替你开窍！</c>\n\nsrc-240\n00:15:49.241 --> 00:15:51.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他提高黑人、妇女地位</c>\n\nsrc-241\n00:15:51.709 --> 00:15:53.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他重视女人</c>\n\nsrc-242\n00:15:53.544 --> 00:15:55.372 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他当州长</c>\n\nsrc-243\n00:15:55.455 --> 00:15:58.007 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>改革医疗制度</c>\n\nsrc-244\n00:15:58.048 --> 00:16:00.836 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对不起\n- 我睡过去</c>\n\nsrc-245\n00:16:00.919 --> 00:16:03.630 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>欢迎醒来迎接新美国</c>\n\nsrc-246\n00:16:03.714 --> 00:16:05.465 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>话题很有趣</c>\n\nsrc-247\n00:16:05.549 --> 00:16:08.927 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你说得对，你什么都不是\n- 我什么都不是</c>\n\nsrc-248\n00:16:10.762 --> 00:16:13.640 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家看！</c>\n\nsrc-249\n00:16:14.189 --> 00:16:16.935 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>情人</c>\n\nsrc-250\n00:16:18.103 --> 00:16:22.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了保护他，隐瞒我们的关系</c>\n\nsrc-251\n00:16:22.149 --> 00:16:24.776 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>事实是，我爱他</c>\n\nsrc-252\n00:16:26.695 --> 00:16:28.780 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没法再隐瞒，他叫我否认……</c>\n\nsrc-253\n00:16:28.864 --> 00:16:34.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没法再否认，我没法再骗人</c>\n\nsrc-254\n00:16:35.329 --> 00:16:39.881 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有一点你说得对，他重视女人</c>\n\nsrc-255\n00:16:39.964 --> 00:16:42.961 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你我很投契\n- 拜拜，厕纸佬</c>\n\nsrc-256\n00:16:43.045 --> 00:16:45.047 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拜拜，复印妹</c>\n\nsrc-257\n00:16:45.553 --> 00:16:49.092 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>惨，播个不停</c>\n\nsrc-258\n00:16:49.176 --> 00:16:51.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>迟早会淡化，大家不会再理会</c>\n\nsrc-259\n00:16:51.720 --> 00:16:56.183 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布什</c>\n\nsrc-260\n00:16:56.266 --> 00:16:59.394 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>布什可以，克林顿就不行？</c>\n\nsrc-261\n00:16:59.478 --> 00:17:01.313 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>摆明不是正经女人</c>\n\nsrc-262\n00:17:01.396 --> 00:17:04.614 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>难怪成为克林顿的痛脚</c>\n\nsrc-263\n00:17:04.733 --> 00:17:06.944 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>人人都有弱点</c>\n\nsrc-264\n00:17:07.027 --> 00:17:11.329 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老爸喜欢留长假指甲的红发胖女人</c>\n\nsrc-265\n00:17:11.412 --> 00:17:12.532 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>反胃</c>\n\nsrc-266\n00:17:12.616 --> 00:17:14.749 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>惹人讨厌</c>\n\nsrc-267\n00:17:14.791 --> 00:17:18.747 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喜欢</c>\n\nsrc-268\n00:17:18.795 --> 00:17:19.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你知道我喜欢什么吗？</c>\n\nsrc-269\n00:17:20.046 --> 00:17:22.291 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>褐色长发、戴龟甲眼镜……</c>\n\nsrc-270\n00:17:22.376 --> 00:17:24.545 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>像外星人那种女人</c>\n\nsrc-271\n00:17:24.627 --> 00:17:25.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我照杀</c>\n\nsrc-272\n00:17:26.003 --> 00:17:29.264 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢喜欢我的男人</c>\n\nsrc-273\n00:17:30.342 --> 00:17:32.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你心理有问题，我想祝酒</c>\n\nsrc-274\n00:17:34.137 --> 00:17:36.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>向克林顿和他弱点干杯</c>\n\nsrc-275\n00:17:45.983 --> 00:17:47.734 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂！是我！</c>\n\nsrc-276\n00:17:47.818 --> 00:17:49.444 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是艾美莉？</c>\n\nsrc-277\n00:17:49.528 --> 00:17:51.530 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉！</c>\n\nsrc-278\n00:17:51.613 --> 00:17:52.739 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么声音？</c>\n\nsrc-279\n00:17:52.823 --> 00:17:56.451 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没什么\n两条傻佬，自己没有红颜知己……</c>\n\nsrc-280\n00:17:56.535 --> 00:18:01.081 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>于是眼红，拿我来开玩笑</c>\n\nsrc-281\n00:18:01.164 --> 00:18:02.291 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你喝醉</c>\n\nsrc-282\n00:18:02.374 --> 00:18:03.709 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你真漂亮</c>\n\nsrc-283\n00:18:03.792 --> 00:18:06.879 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你醉了\n- 你很漂亮</c>\n\nsrc-284\n00:18:07.838 --> 00:18:10.429 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉，来纽约吧</c>\n\nsrc-285\n00:18:10.470 --> 00:18:13.302 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你会喜欢这里的活力……</c>\n\nsrc-286\n00:18:13.385 --> 00:18:17.514 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>活力？你的意思不会只是活力</c>\n\nsrc-287\n00:18:17.598 --> 00:18:19.187 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\nsrc-288\n00:18:20.100 --> 00:18:21.810 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不会回来</c>\n\nsrc-289\n00:18:21.894 --> 00:18:25.898 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要那样说，来一起渡周末吧</c>\n\nsrc-290\n00:18:27.065 --> 00:18:29.067 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说得对，对不起</c>\n\nsrc-291\n00:18:30.527 --> 00:18:32.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有没有找阿夏？</c>\n\nsrc-292\n00:18:32.783 --> 00:18:36.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没有，我留下口信，她没有回复</c>\n\nsrc-293\n00:18:38.702 --> 00:18:41.413 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没事吧？</c>\n\nsrc-294\n00:18:41.496 --> 00:18:43.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>觉得寂寞</c>\n\nsrc-295\n00:18:43.582 --> 00:18:46.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想你想到发癫，好辛苦</c>\n\nsrc-296\n00:18:48.212 --> 00:18:50.343 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我明白你意思</c>\n\nsrc-297\n00:19:12.152 --> 00:19:16.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你未睡？\n- 罗素先生</c>\n\nsrc-298\n00:19:16.573 --> 00:19:20.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你望小包望了一个星期</c>\n\nsrc-299\n00:19:22.079 --> 00:19:24.915 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今晚怎样？大概有进展吧？</c>\n\nsrc-300\n00:19:24.998 --> 00:19:30.003 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这次认真麻烦，我爱上这女孩！</c>\n\nsrc-301\n00:19:30.671 --> 00:19:32.133 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好事</c>\n\nsrc-302\n00:19:32.217 --> 00:19:35.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我将来出任首位黑人总统……</c>\n\nsrc-303\n00:19:35.092 --> 00:19:37.928 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>陪我就职宣誓的是茱莉亚罗拔丝</c>\n\nsrc-304\n00:19:38.011 --> 00:19:40.931 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你想像力非常丰富</c>\n\nsrc-305\n00:19:41.014 --> 00:19:44.434 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>由一夜情联想到做总统</c>\n\nsrc-306\n00:19:46.019 --> 00:19:47.357 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拆吧</c>\n\nsrc-307\n00:19:47.399 --> 00:19:50.524 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你心痒难抵，好想拆</c>\n\nsrc-308\n00:19:50.607 --> 00:19:54.403 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>名字叫阿夏，已经香艳……看！</c>\n\nsrc-309\n00:19:54.486 --> 00:19:57.197 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你撕开了一点！我看到</c>\n\nsrc-310\n00:19:57.281 --> 00:20:00.117 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拆吧，怕什么？</c>\n\nsrc-311\n00:20:00.200 --> 00:20:02.035 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-312\n00:20:06.999 --> 00:20:09.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 日记\n- 正</c>\n\nsrc-313\n00:20:09.421 --> 00:20:13.632 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要抢！不可以看</c>\n\nsrc-314\n00:20:14.425 --> 00:20:18.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>草坪对面是男生宿舍……\n看得见他们的窗口</c>\n\nsrc-315\n00:20:19.388 --> 00:20:21.930 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>晚上又热又湿</c>\n\nsrc-316\n00:20:22.014 --> 00:20:26.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们衣不蔽体，假装男生看不见</c>\n\nsrc-317\n00:20:26.393 --> 00:20:29.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其中几个颇大胆，我的新相识……</c>\n\nsrc-318\n00:20:30.230 --> 00:20:32.232 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉甜美可人</c>\n\nsrc-319\n00:20:33.192 --> 00:20:37.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有点缅腼，观望我反应</c>\n\nsrc-320\n00:20:37.863 --> 00:20:42.701 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>读下去！精彩，读到哪儿了？</c>\n\nsrc-321\n00:20:43.368 --> 00:20:47.291 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我们最后一晚，期待了好几天</c>\n\nsrc-322\n00:20:47.333 --> 00:20:49.877 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我与艾美莉最后才走</c>\n\nsrc-323\n00:20:49.960 --> 00:20:54.671 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>走到梯间，我一把抓住她手腕</c>\n\nsrc-324\n00:20:54.755 --> 00:21:00.177 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她仰望我，带着期待眼神\n我料到会怎样发展</c>\n\nsrc-325\n00:21:00.260 --> 00:21:02.262 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也料到</c>\n\nsrc-326\n00:21:02.346 --> 00:21:04.806 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>犀利！</c>\n\nsrc-327\n00:21:05.349 --> 00:21:08.393 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干什么？正精彩呢！</c>\n\nsrc-328\n00:21:10.395 --> 00:21:12.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等一等</c>\n\nsrc-329\n00:21:13.398 --> 00:21:15.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那是你的艾美莉？</c>\n\nsrc-330\n00:21:15.734 --> 00:21:17.611 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>晚安，罗素！</c>\n\nsrc-331\n00:21:18.278 --> 00:21:20.239 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是双性恋！</c>\n\nsrc-332\n00:21:20.322 --> 00:21:22.616 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把照片放回去！</c>\n\nadd-release-donor-370\n00:21:36.463 --> 00:21:37.798 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哇。</c>\n\nsrc-333\n00:21:42.845 --> 00:21:46.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谁？\n- 威廉 希斯，我打过电话来</c>\n\nsrc-334\n00:21:47.641 --> 00:21:50.018 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是来传教？</c>\n\nsrc-335\n00:21:50.102 --> 00:21:51.353 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是</c>\n\nsrc-336\n00:21:51.436 --> 00:21:53.313 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哗，是高佬</c>\n\nsrc-337\n00:21:55.607 --> 00:21:57.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好</c>\n\nsrc-338\n00:22:07.619 --> 00:22:09.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>进来</c>\n\nsrc-339\n00:22:09.663 --> 00:22:11.665 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>顺手关门</c>\n\nsrc-340\n00:22:12.749 --> 00:22:13.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上锁！</c>\n\nsrc-341\n00:22:14.793 --> 00:22:19.131 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏会回来，叫你耐心等</c>\n\nsrc-342\n00:22:19.214 --> 00:22:24.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 里面是什么？\n- 不知道，你是阿夏的父亲？</c>\n\nsrc-343\n00:22:24.803 --> 00:22:26.763 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对，我是她爸爸</c>\n\nsrc-344\n00:22:41.403 --> 00:22:44.448 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 喝一杯？\n- 不用了，现在还有点早</c>\n\nsrc-345\n00:22:44.531 --> 00:22:46.950 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>乡巴佬</c>\n\nsrc-346\n00:22:47.034 --> 00:22:51.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自我介绍一下吧，有什么志向？</c>\n\nsrc-347\n00:22:51.997 --> 00:22:55.209 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有什么理想？喜爱？</c>\n\nsrc-348\n00:22:55.292 --> 00:22:57.878 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长大想做什么？</c>\n\nsrc-349\n00:22:57.961 --> 00:22:59.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>坐</c>\n\nsrc-350\n00:22:59.338 --> 00:23:00.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在做什么？</c>\n\nsrc-351\n00:23:00.797 --> 00:23:02.174 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是替爸爸办事吧？</c>\n\nsrc-352\n00:23:02.257 --> 00:23:03.383 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要说出来！</c>\n\nsrc-353\n00:23:03.467 --> 00:23:04.718 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>华尔街，不是！</c>\n\nsrc-354\n00:23:04.801 --> 00:23:07.888 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>律师事务所</c>\n\nsrc-355\n00:23:07.971 --> 00:23:10.933 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我放弃，你做什么？</c>\n\nsrc-356\n00:23:11.016 --> 00:23:14.561 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我替克林顿办事，他参选总统</c>\n\nsrc-357\n00:23:14.645 --> 00:23:16.270 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是吧</c>\n\nsrc-358\n00:23:16.647 --> 00:23:20.692 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我比克林顿的妈妈更熟悉克林顿</c>\n\nsrc-359\n00:23:20.776 --> 00:23:21.818 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\nsrc-360\n00:23:21.902 --> 00:23:24.530 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你做什么？\n- 我做什么？</c>\n\nsrc-361\n00:23:24.613 --> 00:23:26.281 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喝酒！</c>\n\nsrc-362\n00:23:26.322 --> 00:23:27.907 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>饮！</c>\n\nsrc-363\n00:23:28.200 --> 00:23:29.993 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>做个真汉子</c>\n\nsrc-364\n00:23:32.663 --> 00:23:34.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对！舒服点吧？</c>\n\nsrc-365\n00:23:35.999 --> 00:23:37.543 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吞下去！</c>\n\nsrc-366\n00:23:39.211 --> 00:23:41.171 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>讲讲克林顿的事</c>\n\nsrc-367\n00:23:44.716 --> 00:23:46.844 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嘿，醒醒。</c>\n\nsrc-368\n00:23:57.185 --> 00:23:59.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要阿司匹林吗？</c>\n\nsrc-369\n00:24:05.571 --> 00:24:07.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你必定是威廉</c>\n\nsrc-370\n00:24:08.532 --> 00:24:11.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你酒量比我男朋友还好</c>\n\nsrc-371\n00:24:12.369 --> 00:24:16.832 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他不是你爸？\n- 他那样说？</c>\n\nsrc-372\n00:24:16.915 --> 00:24:19.001 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他是我的论文导师</c>\n\nsrc-373\n00:24:20.586 --> 00:24:21.795 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他还说什么？</c>\n\nsrc-374\n00:24:21.879 --> 00:24:26.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要做真汉子，不要做臭小子</c>\n\nsrc-375\n00:24:26.631 --> 00:24:28.719 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你从他处学到什么？</c>\n\nsrc-376\n00:24:29.428 --> 00:24:31.680 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>学到要灌酒</c>\n\nsrc-377\n00:24:31.763 --> 00:24:34.016 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>打架</c>\n\nsrc-378\n00:24:34.099 --> 00:24:35.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 也要性？\n- 对</c>\n\nsrc-379\n00:24:35.642 --> 00:24:37.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真汉子不那样叫</c>\n\nsrc-380\n00:24:37.311 --> 00:24:39.354 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎样叫？</c>\n\nsrc-381\n00:24:40.606 --> 00:24:44.735 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉托我带件东西给你</c>\n\nsrc-382\n00:24:45.736 --> 00:24:49.945 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好久没跟她联络\n- 我们打算秋天后一起生活</c>\n\nsrc-383\n00:24:52.117 --> 00:24:54.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拜托！爸爸</c>\n\nsrc-384\n00:24:58.916 --> 00:25:00.709 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要！</c>\n\nsrc-385\n00:25:08.175 --> 00:25:10.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她等待我反应，我吻她</c>\n\nsrc-386\n00:25:12.930 --> 00:25:14.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你读过？</c>\n\nsrc-387\n00:25:15.307 --> 00:25:16.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没有</c>\n\nsrc-388\n00:25:20.187 --> 00:25:22.523 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 读过一页\n- 一页</c>\n\nsrc-389\n00:25:22.606 --> 00:25:24.274 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>顶多两页</c>\n\nsrc-390\n00:25:24.358 --> 00:25:27.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你和艾美莉又摸又亲的那部分</c>\n\nsrc-391\n00:25:28.237 --> 00:25:33.367 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那部分，哦\n- 写得非常传神，历历在目</c>\n\nsrc-392\n00:25:33.450 --> 00:25:35.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你文笔一流，我意思是……</c>\n\nsrc-393\n00:25:35.449 --> 00:25:38.413 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给你，寂寞时读</c>\n\nsrc-394\n00:25:38.497 --> 00:25:42.835 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不可以，是你的日记\n- 我用不着</c>\n\nsrc-395\n00:25:42.918 --> 00:25:44.711 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>已经入了我脑</c>\n\nsrc-396\n00:25:44.795 --> 00:25:48.298 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你保留手稿吧</c>\n\nsrc-397\n00:25:49.383 --> 00:25:52.507 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不明白艾美莉为什么托你送来</c>\n\nsrc-398\n00:25:55.806 --> 00:25:57.303 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>咸顿</c>\n\nsrc-399\n00:25:58.471 --> 00:26:00.310 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你醒了？</c>\n\nsrc-400\n00:26:00.394 --> 00:26:02.646 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>咸顿是顶尖作家</c>\n\nsrc-401\n00:26:02.729 --> 00:26:04.602 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>写过麦高文……</c>\n\nsrc-402\n00:26:06.483 --> 00:26:08.777 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你们……\n- 对，我们</c>\n\nsrc-403\n00:26:09.941 --> 00:26:13.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有没有同六十几岁的人搞过？</c>\n\nsrc-404\n00:26:13.115 --> 00:26:16.285 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 没有\n- 那不要批判</c>\n\nsrc-405\n00:26:16.368 --> 00:26:19.284 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有批判</c>\n\nsrc-406\n00:26:19.413 --> 00:26:22.662 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有才有貌、文采风流</c>\n\nsrc-407\n00:26:22.745 --> 00:26:23.788 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-408\n00:26:23.876 --> 00:26:26.253 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要讨你欢心，必须是……</c>\n\nsrc-409\n00:26:26.336 --> 00:26:27.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真汉子\n- 对</c>\n\nsrc-410\n00:26:28.046 --> 00:26:32.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我好难比得上\n- 除非你不怕货比货</c>\n\nsrc-411\n00:26:34.011 --> 00:26:38.265 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 幸会\n- 我也是</c>\n\nsrc-412\n00:26:38.348 --> 00:26:41.018 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不好意思，要你割爱……</c>\n\nsrc-413\n00:26:53.697 --> 00:26:55.319 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起</c>\n\nsrc-414\n00:26:56.033 --> 00:26:58.118 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是好奇</c>\n\nsrc-415\n00:26:58.614 --> 00:27:01.955 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>咸顿鼓励我培养好奇心</c>\n\nsrc-416\n00:27:03.457 --> 00:27:05.834 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他说那是当好记者的要诀</c>\n\nsrc-417\n00:27:07.920 --> 00:27:10.964 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨默！爸爸饿了！</c>\n\nsrc-418\n00:27:12.132 --> 00:27:14.635 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>话口未完，我还是回去</c>\n\nsrc-419\n00:27:14.718 --> 00:27:16.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你去了哪里？</c>\n\nsrc-420\n00:27:17.888 --> 00:27:21.308 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有空打来，一起吃晚餐</c>\n\nsrc-421\n00:27:21.391 --> 00:27:23.143 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很乐意</c>\n\nsrc-422\n00:27:27.105 --> 00:27:29.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你会约她吗？\n- 你发神经吗？</c>\n\nsrc-423\n00:27:29.733 --> 00:27:33.028 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你打算怎样？\n- 我打算怎样？</c>\n\nsrc-424\n00:27:33.111 --> 00:27:37.616 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一条心，同艾美莉组织二人世界</c>\n\nsrc-425\n00:27:37.699 --> 00:27:39.576 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可能变一王两后</c>\n\nsrc-426\n00:27:39.660 --> 00:27:42.329 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老头子不走，可能变两王两后</c>\n\nsrc-427\n00:27:42.412 --> 00:27:44.248 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没有帮我</c>\n\nsrc-428\n00:27:45.082 --> 00:27:49.711 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不应该打开日记，自投欲海</c>\n\nsrc-429\n00:27:50.546 --> 00:27:52.458 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一王两后是什么？</c>\n\nsrc-430\n00:27:52.583 --> 00:27:54.293 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一王两后</c>\n\nsrc-431\n00:27:56.260 --> 00:28:00.264 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大人闷极无聊所玩的游戏</c>\n\nsrc-432\n00:28:03.141 --> 00:28:06.019 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>小儿科，艾美莉怎样？</c>\n\nsrc-433\n00:28:06.103 --> 00:28:08.605 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没怎样，我打算等她来……</c>\n\nsrc-434\n00:28:08.689 --> 00:28:11.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让她出其不意</c>\n\nsrc-435\n00:28:12.776 --> 00:28:15.863 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>离初选一星期……</c>\n\nsrc-436\n00:28:15.946 --> 00:28:20.409 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我买够面包厕纸，晋升去制造标语</c>\n\nsrc-437\n00:28:23.203 --> 00:28:25.205 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哎唷！</c>\n\nsrc-438\n00:28:27.624 --> 00:28:29.626 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在这里做什么？</c>\n\nsrc-439\n00:28:33.422 --> 00:28:37.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>挪开！挪开一点！</c>\n\nsrc-440\n00:28:38.051 --> 00:28:40.220 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>挪开！</c>\n\nsrc-441\n00:28:45.142 --> 00:28:50.098 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>新标语做好</c>\n\nsrc-442\n00:28:50.181 --> 00:28:53.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我替史云尼议员写过演词</c>\n\nsrc-443\n00:28:53.650 --> 00:28:54.902 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你中学毕业未？</c>\n\nsrc-444\n00:28:54.985 --> 00:28:58.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这位布什是德州人，但不是总统</c>\n\nsrc-445\n00:28:58.989 --> 00:29:03.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是总统的长子、白宫的重要顾问</c>\n\nsrc-446\n00:29:03.535 --> 00:29:05.454 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也是流浪棒球队领队</c>\n\nsrc-447\n00:29:06.663 --> 00:29:08.540 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>应该继续搞棒球</c>\n\nsrc-448\n00:29:08.624 --> 00:29:10.785 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对\n- 有没有见到希斯？</c>\n\nsrc-449\n00:29:11.543 --> 00:29:14.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希斯！希斯呢？</c>\n\nsrc-450\n00:29:15.631 --> 00:29:18.509 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在麦迪逊镇读书考第一？</c>\n\nsrc-451\n00:29:19.501 --> 00:29:22.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来，跟我走</c>\n\nsrc-452\n00:29:22.304 --> 00:29:24.348 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纽约的麦迪逊旧生名单</c>\n\nsrc-453\n00:29:24.431 --> 00:29:26.266 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>二十万</c>\n\nsrc-454\n00:29:26.350 --> 00:29:29.770 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>星期一举办筹款餐会</c>\n\nsrc-455\n00:29:29.853 --> 00:29:32.314 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一万一位，你推销五围</c>\n\nsrc-456\n00:29:32.397 --> 00:29:34.107 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不用买外卖？</c>\n\nsrc-457\n00:29:34.191 --> 00:29:35.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 暂时不用\n- 卡拉夫</c>\n\nsrc-458\n00:29:36.769 --> 00:29:39.696 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你，我很开心</c>\n\nsrc-459\n00:29:39.780 --> 00:29:41.615 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>得</c>\n\nsrc-460\n00:29:41.698 --> 00:29:45.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你的办公桌\n- 看</c>\n\nsrc-461\n00:29:46.912 --> 00:29:49.122 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好搞笑，厕纸</c>\n\nsrc-462\n00:29:49.206 --> 00:29:51.667 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有趣就有趣在它很讽刺</c>\n\nsrc-463\n00:29:51.750 --> 00:29:54.670 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家看吧</c>\n\nsrc-464\n00:29:55.337 --> 00:29:57.631 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有台、有名单</c>\n\nsrc-465\n00:29:57.714 --> 00:30:00.759 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有电话、有空箩</c>\n\nsrc-466\n00:30:00.843 --> 00:30:05.973 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不认为克林顿值得非议</c>\n\nsrc-467\n00:30:06.056 --> 00:30:11.144 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有一半美国人主张大麻合法化</c>\n\nsrc-468\n00:30:11.228 --> 00:30:12.271 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂？</c>\n\nsrc-469\n00:30:12.354 --> 00:30:15.315 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他没有逃避兵役</c>\n\nsrc-470\n00:30:15.399 --> 00:30:18.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>何况，大部分美国人……</c>\n\nsrc-471\n00:30:18.402 --> 00:30:21.479 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>认为不应该打越战</c>\n\nsrc-472\n00:30:22.072 --> 00:30:23.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>两条腿</c>\n\nsrc-473\n00:30:23.490 --> 00:30:26.317 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你必定很不习惯失去两条</c>\n\nsrc-474\n00:30:28.319 --> 00:30:33.750 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我明白，不过你要记着……</c>\n\nsrc-475\n00:30:35.919 --> 00:30:38.797 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿出生地点叫希望镇</c>\n\nsrc-476\n00:30:39.631 --> 00:30:43.051 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他所代表的正是希望</c>\n\nsrc-477\n00:30:43.135 --> 00:30:46.680 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我明白俗套，不过……</c>\n\nsrc-478\n00:30:46.763 --> 00:30:50.517 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我国不能故作清高</c>\n\nsrc-479\n00:30:52.302 --> 00:30:55.564 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那太好了，该我谢谢你才对</c>\n\nsrc-480\n00:30:55.647 --> 00:30:57.107 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>两位</c>\n\nsrc-481\n00:30:57.599 --> 00:30:59.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你，比舒先生</c>\n\nsrc-482\n00:31:01.236 --> 00:31:03.697 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下星期四的晚宴</c>\n\nsrc-483\n00:31:04.781 --> 00:31:06.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希拉里告诉我……</c>\n\nsrc-484\n00:31:06.533 --> 00:31:11.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她想见见我们最重要的支持者</c>\n\nsrc-485\n00:31:11.788 --> 00:31:14.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你必定乐意见到她</c>\n\nsrc-486\n00:31:17.252 --> 00:31:20.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你想包一围</c>\n\nsrc-487\n00:31:20.172 --> 00:31:24.468 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>欢迎之至，我就记低你包一围</c>\n\nsrc-488\n00:31:24.551 --> 00:31:26.678 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好极，下星期四再见</c>\n\nsrc-489\n00:31:26.762 --> 00:31:28.472 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-490\n00:31:31.725 --> 00:31:35.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我推销了一围，承惠五万大元</c>\n\nsrc-491\n00:31:41.642 --> 00:31:44.102 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有你的</c>\n\nsrc-492\n00:31:48.607 --> 00:31:51.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>厕纸佬！</c>\n\nsrc-493\n00:31:52.496 --> 00:31:55.363 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好，一包红牌，麻烦你</c>\n\nsrc-494\n00:31:55.446 --> 00:31:58.085 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>$3.60，新税与新警告</c>\n\nsrc-495\n00:31:59.127 --> 00:32:00.284 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>离谱</c>\n\nsrc-496\n00:32:00.326 --> 00:32:01.797 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>警告：吸烟导致缓慢而痛苦死亡</c>\n\nsrc-497\n00:32:01.880 --> 00:32:05.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿有没有把大麻索入肺？</c>\n\nsrc-498\n00:32:05.540 --> 00:32:09.585 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你女友明明把你捉奸在床……</c>\n\nsrc-499\n00:32:09.627 --> 00:32:11.045 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你却说：我们没有越轨</c>\n\nsrc-500\n00:32:11.056 --> 00:32:14.518 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 难道她会信？\n- 会</c>\n\nsrc-501\n00:32:15.550 --> 00:32:17.938 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一包美鹰，麻烦你</c>\n\nsrc-502\n00:32:18.021 --> 00:32:19.470 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>$4.25</c>\n\nsrc-503\n00:32:19.565 --> 00:32:23.193 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你吸$4.25包的香烟？</c>\n\nsrc-504\n00:32:23.277 --> 00:32:25.112 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>添加剂比较少</c>\n\nsrc-505\n00:32:25.195 --> 00:32:27.990 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 『健康香烟』\n- 可以这样说</c>\n\nsrc-506\n00:32:28.073 --> 00:32:33.287 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>少添加剂，不应该比较便宜吗？</c>\n\nsrc-507\n00:32:33.370 --> 00:32:36.081 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的香烟有硝酸钾</c>\n\nsrc-508\n00:32:36.164 --> 00:32:39.615 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>燃烧得快，于是吸得多</c>\n\nsrc-509\n00:32:39.699 --> 00:32:45.257 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到头来，你的香烟……\n反而比较贵，不是比较平</c>\n\nsrc-510\n00:32:47.664 --> 00:32:50.470 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>复印妹，你买的……</c>\n\nsrc-511\n00:32:50.554 --> 00:32:53.599 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不仅是烟，而是花巧的包装</c>\n\nsrc-512\n00:32:53.682 --> 00:32:58.145 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只能用来自我安慰，没有其他</c>\n\nsrc-513\n00:32:58.729 --> 00:33:00.606 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你想打赌？\n- 好</c>\n\nsrc-514\n00:33:00.689 --> 00:33:03.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 赌二十块\n- 我有二十块</c>\n\nsrc-515\n00:33:03.179 --> 00:33:05.098 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会赢得轻易</c>\n\nsrc-516\n00:33:05.861 --> 00:33:07.487 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一分钟后，我袋内有四十块</c>\n\nsrc-517\n00:33:07.571 --> 00:33:10.824 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一起索，索同样时间</c>\n\nsrc-518\n00:33:11.688 --> 00:33:13.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>准备，开始</c>\n\nsrc-519\n00:33:23.003 --> 00:33:26.381 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 今天是我生日\n- 生日快乐</c>\n\nsrc-520\n00:33:35.557 --> 00:33:37.851 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不庆祝？</c>\n\nsrc-521\n00:33:38.477 --> 00:33:42.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>男友本来请我吃饭，然后去派对</c>\n\nsrc-522\n00:33:42.481 --> 00:33:47.319 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但费城临时有演唱机会……他当然去唱</c>\n\nsrc-523\n00:33:56.078 --> 00:33:57.788 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他想做摇滚友高彬</c>\n\nsrc-524\n00:33:57.871 --> 00:34:00.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实，比起当我的男朋友\n他更想成为下一个科特·柯本</c>\n\nsrc-525\n00:34:01.291 --> 00:34:03.072 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谁是高彬？</c>\n\nsrc-526\n00:34:04.336 --> 00:34:06.046 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你讲笑？</c>\n\nsrc-527\n00:34:07.297 --> 00:34:08.911 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\nsrc-528\n00:34:09.382 --> 00:34:10.676 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>索</c>\n\nsrc-529\n00:34:17.224 --> 00:34:19.810 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看</c>\n\nsrc-530\n00:34:26.929 --> 00:34:28.652 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不用</c>\n\nsrc-531\n00:34:28.735 --> 00:34:30.237 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>证实我对你错</c>\n\nsrc-532\n00:34:30.320 --> 00:34:33.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我已经满足</c>\n\nsrc-533\n00:34:33.489 --> 00:34:35.701 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>愿赌服输</c>\n\nsrc-534\n00:34:35.784 --> 00:34:39.107 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不如改为请你吃生日饭</c>\n\nsrc-535\n00:34:39.189 --> 00:34:40.246 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你想约会？</c>\n\nsrc-536\n00:34:40.330 --> 00:34:41.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是</c>\n\nsrc-537\n00:34:42.081 --> 00:34:43.583 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是同情你</c>\n\nsrc-538\n00:34:43.667 --> 00:34:47.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你生日却没有节目</c>\n\nsrc-539\n00:34:47.115 --> 00:34:48.880 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样吧</c>\n\nsrc-540\n00:34:48.964 --> 00:34:50.924 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你陪我去派对</c>\n\nsrc-541\n00:34:51.007 --> 00:34:53.969 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>免得我单拖</c>\n\nadd-release-donor-599\n00:35:01.351 --> 00:35:03.770 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好，我会……</c>\n\nsrc-542\n00:35:08.525 --> 00:35:10.819 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得不配来</c>\n\nsrc-543\n00:35:10.903 --> 00:35:12.738 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说得对</c>\n\nsrc-544\n00:35:17.326 --> 00:35:20.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉是谁？你的学生情人？</c>\n\nsrc-545\n00:35:20.579 --> 00:35:22.539 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你实在妙不可言</c>\n\nsrc-546\n00:35:22.623 --> 00:35:24.208 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以把普通一句话……</c>\n\nsrc-547\n00:35:24.291 --> 00:35:27.503 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>贬得一文不值</c>\n\nsrc-548\n00:35:27.586 --> 00:35:30.589 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 佩服佩服\n- 我不是故意</c>\n\nsrc-549\n00:35:30.672 --> 00:35:33.091 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我认为令人艳羡</c>\n\nsrc-550\n00:35:33.175 --> 00:35:34.551 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你又来\n- 真的？</c>\n\nsrc-551\n00:35:34.635 --> 00:35:36.053 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我甚至不自觉</c>\n\nsrc-552\n00:35:36.136 --> 00:35:39.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可能无法想像，男女关系……</c>\n\nsrc-553\n00:35:39.389 --> 00:35:43.185 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以互相尊重，毫无自虐意味</c>\n\nsrc-554\n00:35:43.268 --> 00:35:46.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你同艾美莉既然幸福无比……</c>\n\nsrc-555\n00:35:46.438 --> 00:35:48.232 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不娶她？</c>\n\nsrc-556\n00:35:48.315 --> 00:35:50.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谁阻止你？</c>\n\nsrc-557\n00:35:51.276 --> 00:35:52.888 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没有人</c>\n\nsrc-558\n00:35:58.617 --> 00:36:00.494 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>明天送给她</c>\n\nsrc-559\n00:36:00.577 --> 00:36:02.829 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>带她去名贵餐厅</c>\n\nsrc-560\n00:36:02.913 --> 00:36:06.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大庭广众求婚？</c>\n\nsrc-561\n00:36:06.208 --> 00:36:10.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对，怕什么？\n- 自信的表示</c>\n\nsrc-562\n00:36:10.921 --> 00:36:12.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>打算怎样求？</c>\n\nsrc-563\n00:36:12.089 --> 00:36:14.967 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 研究中\n- 当我做艾美莉吧</c>\n\nsrc-564\n00:36:15.050 --> 00:36:19.555 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用我来练习</c>\n\nsrc-565\n00:36:19.638 --> 00:36:24.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是艾美莉，你的学生情人\n你想问我什么？</c>\n\nsrc-566\n00:36:24.101 --> 00:36:26.353 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 艾美莉\n- 等一等！下跪</c>\n\nsrc-567\n00:36:26.436 --> 00:36:28.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不跪</c>\n\nsrc-568\n00:36:28.480 --> 00:36:31.024 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她会喜欢你跪</c>\n\nsrc-569\n00:36:31.108 --> 00:36:36.154 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我不会跪\n- 错得很，算了</c>\n\nsrc-570\n00:36:36.488 --> 00:36:38.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 艾美莉\n- 怎样？威廉</c>\n\nsrc-571\n00:36:38.599 --> 00:36:40.977 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要逗我笑，艾美莉……</c>\n\nsrc-572\n00:36:41.451 --> 00:36:43.354 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你愿不愿意……</c>\n\nsrc-573\n00:36:46.707 --> 00:36:48.166 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嫁给我</c>\n\nsrc-574\n00:36:48.959 --> 00:36:52.045 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不愿意\n- 吓</c>\n\nsrc-575\n00:36:52.129 --> 00:36:53.964 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『愿不愿意嫁给我』？</c>\n\nsrc-576\n00:36:54.047 --> 00:36:58.844 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你求婚求得木口木面</c>\n\nsrc-577\n00:36:58.927 --> 00:37:02.806 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要我放弃自由自在的生活……</c>\n\nsrc-578\n00:37:02.890 --> 00:37:04.266 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放弃享受人生的机会……</c>\n\nsrc-579\n00:37:04.349 --> 00:37:07.019 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了一种名过其实的制度？</c>\n\nsrc-580\n00:37:07.102 --> 00:37:10.856 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你娶我嫁，为的是什么？</c>\n\nsrc-581\n00:37:10.939 --> 00:37:14.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只为满足根深蒂固的中产欲望……</c>\n\nsrc-582\n00:37:14.484 --> 00:37:17.345 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>从而达至资本主义的消费目的</c>\n\nsrc-583\n00:37:18.947 --> 00:37:20.866 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吓！</c>\n\nsrc-584\n00:37:20.949 --> 00:37:24.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你应该跪下\n- 闭嘴！</c>\n\nsrc-585\n00:37:28.790 --> 00:37:31.293 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想娶你，因为你是唯一</c>\n\nsrc-586\n00:37:31.376 --> 00:37:33.462 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我早上醒来……</c>\n\nsrc-587\n00:37:33.545 --> 00:37:36.173 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想见的人，也是我临睡想吻的人</c>\n\nsrc-588\n00:37:36.256 --> 00:37:40.052 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为当初见到这对手……</c>\n\nsrc-589\n00:37:40.802 --> 00:37:43.347 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没法想像握不到的心情，不过……</c>\n\nsrc-590\n00:37:43.430 --> 00:37:47.100 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>主要因为，我爱你爱得太深……</c>\n\nsrc-591\n00:37:49.686 --> 00:37:52.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>除了结婚外，别无他法，所以……</c>\n\nsrc-592\n00:37:52.105 --> 00:37:54.525 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你愿不愿意……</c>\n\nsrc-593\n00:38:01.532 --> 00:38:03.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嫁给我？</c>\n\nsrc-594\n00:38:03.909 --> 00:38:06.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>肯定愿意，或者愿意</c>\n\nsrc-595\n00:38:07.621 --> 00:38:09.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要考虑</c>\n\nsrc-596\n00:38:11.875 --> 00:38:13.377 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>送我回家好吗？</c>\n\nsrc-597\n00:38:23.720 --> 00:38:26.849 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 喝茶？\n- 好</c>\n\nsrc-598\n00:38:31.395 --> 00:38:33.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么这样多《简爱》？</c>\n\nsrc-599\n00:38:33.522 --> 00:38:36.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 说来话长\n- 长？</c>\n\nsrc-600\n00:38:37.484 --> 00:38:40.177 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只有三百页左右</c>\n\nsrc-601\n00:38:41.405 --> 00:38:43.347 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>认真说，为什么？</c>\n\nsrc-602\n00:38:44.324 --> 00:38:48.161 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我十三岁生日，希望有对金耳环</c>\n\nsrc-603\n00:38:48.245 --> 00:38:52.457 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爸却送我一本精装《简爱》</c>\n\nsrc-604\n00:38:52.541 --> 00:38:56.795 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>并在扉页题了词，很动人</c>\n\nsrc-605\n00:38:56.879 --> 00:38:59.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有在意，却为耳环而生气</c>\n\nsrc-606\n00:38:59.673 --> 00:39:04.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想不到那是他最后的礼物</c>\n\nsrc-607\n00:39:04.618 --> 00:39:06.138 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么？</c>\n\nsrc-608\n00:39:06.221 --> 00:39:09.080 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>三个星期后，他撞车撞死</c>\n\nsrc-609\n00:39:09.558 --> 00:39:15.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太不幸</c>\n\nsrc-610\n00:39:15.439 --> 00:39:17.380 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有没有读过？</c>\n\nsrc-611\n00:39:18.298 --> 00:39:21.403 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每一两年读一次</c>\n\nsrc-612\n00:39:21.486 --> 00:39:23.780 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>次次不同感受</c>\n\nsrc-613\n00:39:24.823 --> 00:39:29.703 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>后来，我上大学\n我妈卖屋，不知怎样……</c>\n\nsrc-614\n00:39:29.786 --> 00:39:32.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>遗失了《简爱》</c>\n\nsrc-615\n00:39:32.581 --> 00:39:35.918 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在，每次经过书店……</c>\n\nsrc-616\n00:39:36.001 --> 00:39:40.297 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总要看看有没有我爸那一本</c>\n\nsrc-617\n00:39:40.380 --> 00:39:41.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道永远找不到</c>\n\nsrc-618\n00:39:41.673 --> 00:39:46.512 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但执着得幼稚，已经变成……</c>\n\nsrc-619\n00:39:46.595 --> 00:39:49.932 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不幼稚啊\n- 谢谢……习惯</c>\n\nsrc-620\n00:39:50.807 --> 00:39:52.726 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么买这些？</c>\n\nsrc-621\n00:39:53.310 --> 00:39:57.731 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为书内有题词</c>\n\nsrc-622\n00:39:59.733 --> 00:40:03.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『抱着一番诚意，献上重燃希望』</c>\n\nsrc-623\n00:40:07.115 --> 00:40:08.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么歌曲？</c>\n\nsrc-624\n00:40:08.408 --> 00:40:12.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>极乐乐队，高彬主唱，喜欢吗？</c>\n\nsrc-625\n00:40:13.163 --> 00:40:14.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喜欢</c>\n\nsrc-626\n00:40:16.166 --> 00:40:19.086 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我参政是愚蠢</c>\n\nsrc-627\n00:40:19.169 --> 00:40:20.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 确实愚蠢\n- 谢谢</c>\n\nsrc-628\n00:40:21.547 --> 00:40:25.801 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也难怪，你很讨好</c>\n\nsrc-629\n00:40:25.884 --> 00:40:28.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对得很</c>\n\nsrc-630\n00:40:28.720 --> 00:40:32.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者太刻意讨好</c>\n\nsrc-631\n00:40:33.100 --> 00:40:34.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也说得对</c>\n\nsrc-632\n00:40:35.082 --> 00:40:36.959 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我应该让人讨厌我</c>\n\nsrc-633\n00:40:37.563 --> 00:40:40.107 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我得马上设法惹人讨厌，有什么建议？</c>\n\nsrc-634\n00:40:40.190 --> 00:40:41.817 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你已经表现不俗</c>\n\nsrc-635\n00:40:41.900 --> 00:40:43.632 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我已经开始讨厌你了</c>\n\nsrc-636\n00:40:44.194 --> 00:40:45.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>长大想做什么？</c>\n\nsrc-637\n00:40:45.863 --> 00:40:49.491 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你这样聪明，为什么做复印？</c>\n\nsrc-638\n00:40:49.575 --> 00:40:52.619 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不知道！\n- 你还想做什么？</c>\n\nsrc-639\n00:40:52.703 --> 00:40:56.331 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道，也不懂，知不知道？</c>\n\nsrc-640\n00:40:58.750 --> 00:41:01.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我真正想做的是……</c>\n\nsrc-641\n00:41:01.128 --> 00:41:04.923 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到处游历，增长见闻</c>\n\nsrc-642\n00:41:06.049 --> 00:41:08.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在储蓄</c>\n\nsrc-643\n00:41:08.218 --> 00:41:12.806 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大概是因为我和这个男人陷入了僵局</c>\n\nsrc-644\n00:41:12.890 --> 00:41:14.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>撇掉他</c>\n\nsrc-645\n00:41:14.641 --> 00:41:19.500 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我自知多管闲事……但他配你不起</c>\n\nsrc-646\n00:41:19.834 --> 00:41:21.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是事实</c>\n\nsrc-647\n00:41:23.317 --> 00:41:25.986 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 知不知道……\n- 什么？</c>\n\nsrc-648\n00:41:26.069 --> 00:41:29.781 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你我孤男寡女……</c>\n\nsrc-649\n00:41:29.865 --> 00:41:34.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 却不会想入非非\n- 不会</c>\n\nsrc-650\n00:41:35.182 --> 00:41:36.809 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常好</c>\n\nsrc-651\n00:41:54.848 --> 00:41:56.892 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我应该走</c>\n\nsrc-652\n00:42:00.916 --> 00:42:02.542 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>笨蛋！</c>\n\nsrc-653\n00:43:07.940 --> 00:43:09.006 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他来了！</c>\n\nsrc-654\n00:43:09.089 --> 00:43:13.028 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我没说错吧？\n- 我想出乎你意料！</c>\n\nsrc-655\n00:43:13.135 --> 00:43:16.513 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 搭夜机来！\n- 太好了！</c>\n\nsrc-656\n00:43:17.389 --> 00:43:22.538 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我告诉艾美莉……\n你去了阿尔巴尼部署选举</c>\n\nsrc-657\n00:43:22.621 --> 00:43:24.605 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 部署选举\n- 怎样？</c>\n\nsrc-658\n00:43:24.688 --> 00:43:29.735 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 怎样？非常顺利！\n- 好</c>\n\nsrc-659\n00:43:29.818 --> 00:43:33.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为什么在气喘？\n- 刚刚做完运动</c>\n\nsrc-660\n00:43:33.739 --> 00:43:34.757 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跑梯阶</c>\n\nsrc-661\n00:43:34.799 --> 00:43:39.912 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要去办公室，今天很忙\n很高兴认识你</c>\n\nsrc-662\n00:43:43.266 --> 00:43:44.976 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝你好运</c>\n\nadd-release-donor-733\n00:43:48.003 --> 00:43:49.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好。\n- 你好。</c>\n\nadd-release-donor-734\n00:43:50.589 --> 00:43:52.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 坐吧。\n- 好。</c>\n\nadd-release-donor-735\n00:43:54.885 --> 00:43:56.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好。</c>\n\nsrc-663\n00:44:04.353 --> 00:44:06.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇怪，你的舌头味道不一样</c>\n\nsrc-664\n00:44:08.315 --> 00:44:09.834 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>味道不同</c>\n\nsrc-665\n00:44:09.918 --> 00:44:13.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 奇怪\n- 味道不错，只是……不同</c>\n\nsrc-666\n00:44:14.780 --> 00:44:17.032 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者因为这里的水质……</c>\n\nsrc-667\n00:44:17.115 --> 00:44:20.494 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>碱酸度关系……我也莫名奇妙</c>\n\nsrc-668\n00:44:20.577 --> 00:44:23.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我说过你来纽约会变</c>\n\nsrc-669\n00:44:24.748 --> 00:44:26.684 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>散散步好吗？</c>\n\nsrc-670\n00:44:27.125 --> 00:44:29.503 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 呼吸新鲜空气\n- 好，看看纽约</c>\n\nsrc-671\n00:44:31.171 --> 00:44:32.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我有没有……\n- 我正在……</c>\n\nsrc-672\n00:44:32.840 --> 00:44:34.967 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起，说吧</c>\n\nsrc-673\n00:44:35.634 --> 00:44:41.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有没有……\n告诉过你，我爸向我妈求婚情形</c>\n\nsrc-674\n00:44:41.682 --> 00:44:43.534 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没有</c>\n\nsrc-675\n00:44:44.017 --> 00:44:47.271 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爸正去找我妈，打算求婚</c>\n\nsrc-676\n00:44:47.354 --> 00:44:51.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>途中遇见旧女友卡露莲</c>\n\nsrc-677\n00:44:52.734 --> 00:44:55.195 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们交谈，四目相投</c>\n\nsrc-678\n00:44:55.279 --> 00:44:57.197 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>勾起旧情</c>\n\nsrc-679\n00:44:57.281 --> 00:44:59.408 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他在想……</c>\n\nsrc-680\n00:45:00.617 --> 00:45:03.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我可以同卡露莲远走高飞……</c>\n\nsrc-681\n00:45:03.829 --> 00:45:05.539 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快快活活</c>\n\nsrc-682\n00:45:05.622 --> 00:45:07.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只消吻她一吻</c>\n\nsrc-683\n00:45:07.791 --> 00:45:10.961 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过……抬头一望……</c>\n\nsrc-684\n00:45:13.797 --> 00:45:17.176 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>望到我妈拐过弯走来</c>\n\nsrc-685\n00:45:17.968 --> 00:45:21.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那一刻，他知道无须犹疑</c>\n\nsrc-686\n00:45:21.405 --> 00:45:23.098 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>明白吗？</c>\n\nsrc-687\n00:45:25.475 --> 00:45:28.770 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是卡露莲抑或你妈？</c>\n\nsrc-688\n00:45:30.022 --> 00:45:31.273 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是你妈！</c>\n\nsrc-689\n00:45:31.356 --> 00:45:32.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我今天一见你就知</c>\n\nsrc-690\n00:45:32.790 --> 00:45:36.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放回口袋里，不要说</c>\n\nsrc-691\n00:45:36.361 --> 00:45:38.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 等一等\n- 我不用再犹疑</c>\n\nsrc-692\n00:45:38.963 --> 00:45:40.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像我爸……</c>\n\nsrc-693\n00:45:42.091 --> 00:45:44.093 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我同查理上过床！</c>\n\nsrc-694\n00:45:50.433 --> 00:45:52.628 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们不是有计划吗？</c>\n\nsrc-695\n00:45:53.337 --> 00:45:56.981 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你自己有计划，你有大计！</c>\n\nsrc-696\n00:45:57.064 --> 00:45:59.092 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我肯定当时你我都有</c>\n\nsrc-697\n00:45:59.176 --> 00:46:02.638 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们谈过，你有意思</c>\n\nsrc-698\n00:46:02.721 --> 00:46:03.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有意思</c>\n\nsrc-699\n00:46:03.931 --> 00:46:05.448 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但说不出口</c>\n\nsrc-700\n00:46:05.531 --> 00:46:09.353 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>于是跟我室友上床</c>\n\nsrc-701\n00:46:11.355 --> 00:46:13.774 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我自认怯弱，对不起</c>\n\nsrc-702\n00:46:13.857 --> 00:46:15.609 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\nsrc-703\n00:46:22.783 --> 00:46:24.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这次你害得我惨</c>\n\nsrc-704\n00:46:26.078 --> 00:46:28.830 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不是害你，我是还你自由</c>\n\nsrc-705\n00:46:29.915 --> 00:46:31.959 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们一起，只会累斗累</c>\n\nsrc-706\n00:46:32.042 --> 00:46:36.630 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会妨碍你实现大志</c>\n\nsrc-707\n00:46:36.713 --> 00:46:39.508 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到头来你会恨我</c>\n\nsrc-708\n00:46:39.591 --> 00:46:40.843 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我不会\n- 你会</c>\n\nsrc-709\n00:46:40.926 --> 00:46:44.110 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不希望那样，你也不希望</c>\n\nsrc-710\n00:46:44.986 --> 00:46:46.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>信我吧</c>\n\nsrc-711\n00:46:51.034 --> 00:46:53.981 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没有我……</c>\n\nsrc-712\n00:46:54.606 --> 00:46:56.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>反而好</c>\n\nadd-release-donor-794\n00:46:59.403 --> 00:47:00.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对。</c>\n\nsrc-713\n00:47:03.490 --> 00:47:06.827 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>汤 布鲁戈在纽约报道</c>\n\nsrc-714\n00:47:06.910 --> 00:47:09.371 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿虽然备受绯闻打击……</c>\n\nsrc-715\n00:47:09.454 --> 00:47:11.415 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但他不仅大难不死，而且……</c>\n\nsrc-716\n00:47:11.498 --> 00:47:18.422 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在纽约初选中胜出</c>\n\nsrc-717\n00:47:31.101 --> 00:47:32.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纽约、肯萨斯，预期胜出</c>\n\nsrc-718\n00:47:36.579 --> 00:47:41.236 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看见你目露情潮……</c>\n\nsrc-719\n00:47:41.320 --> 00:47:46.366 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大大出乎我意料</c>\n\nsrc-720\n00:47:46.450 --> 00:47:50.704 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来以为……希望落空了</c>\n\nsrc-721\n00:48:06.637 --> 00:48:08.305 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>恭喜</c>\n\nsrc-722\n00:48:08.889 --> 00:48:11.350 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们挽留你，你必定开心</c>\n\nsrc-723\n00:48:11.433 --> 00:48:15.312 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对，开心啊，非常开心</c>\n\nsrc-724\n00:48:15.395 --> 00:48:17.940 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还以为有必要藏起所有利器</c>\n\nsrc-725\n00:48:18.023 --> 00:48:19.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>多奇怪</c>\n\nsrc-726\n00:48:19.775 --> 00:48:23.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没事，但她们的歌喉，听到人半死</c>\n\nsrc-727\n00:48:23.529 --> 00:48:26.615 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她们的舞姿呢？看到就必死</c>\n\nsrc-728\n00:48:29.868 --> 00:48:32.621 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那晚……很对不起</c>\n\nsrc-729\n00:48:32.704 --> 00:48:35.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要紧，我男友不会同意</c>\n\nsrc-730\n00:48:35.624 --> 00:48:37.472 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉也不会</c>\n\nsrc-731\n00:48:38.544 --> 00:48:42.130 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>何况，你同我……好像狗与猫</c>\n\nsrc-732\n00:48:46.093 --> 00:48:49.429 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 油和水\n- 砂纸磨光屁股</c>\n\nsrc-733\n00:48:49.513 --> 00:48:51.890 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真恶心\n- 你就是那个光屁股的</c>\n\nsrc-734\n00:48:51.974 --> 00:48:53.058 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-735\n00:48:53.141 --> 00:48:54.447 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>连侬与麦卡尼</c>\n\nsrc-736\n00:48:54.489 --> 00:48:56.144 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来是拍档</c>\n\nsrc-737\n00:48:56.228 --> 00:48:58.939 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拆档后，连朋友也没法做</c>\n\nsrc-738\n00:49:00.524 --> 00:49:04.027 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我们可以做朋友\n- 我相信可以</c>\n\nsrc-739\n00:49:07.406 --> 00:49:09.408 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 很高兴认识你\n- 干杯</c>\n\nsrc-740\n00:49:13.453 --> 00:49:15.372 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 跳舞吧\n- 不跳</c>\n\nsrc-741\n00:49:15.455 --> 00:49:17.386 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为什么？\n- 好</c>\n\nsrc-742\n00:49:23.547 --> 00:49:25.060 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>走？</c>\n\nsrc-743\n00:49:36.226 --> 00:49:38.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大概再没有艾美莉消息</c>\n\nsrc-744\n00:49:38.115 --> 00:49:42.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想不到她跟查理操练</c>\n\nsrc-745\n00:49:43.650 --> 00:49:47.988 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我也想不到\n- 那剩下爱珮、阿夏</c>\n\nsrc-746\n00:49:48.071 --> 00:49:52.826 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 还有没有？\n- 我忙着助选</c>\n\nsrc-747\n00:49:52.910 --> 00:49:54.536 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿当选后……</c>\n\nsrc-748\n00:49:54.620 --> 00:49:56.830 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗素同我自组公司</c>\n\nsrc-749\n00:49:56.914 --> 00:49:59.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>助人参选</c>\n\nsrc-750\n00:49:59.791 --> 00:50:01.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>参选市政，参选州参议……</c>\n\nsrc-751\n00:50:01.543 --> 00:50:03.347 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>甚至参选捉狗队队长</c>\n\nsrc-752\n00:50:03.420 --> 00:50:07.341 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很有趣，不过女友呢？</c>\n\nsrc-753\n00:50:07.424 --> 00:50:10.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 妈妈呢？\n- 后来我又开始约会了</c>\n\nsrc-754\n00:50:10.469 --> 00:50:14.056 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 但都不认真\n- 艾普丽尔呢？</c>\n\nsrc-755\n00:50:14.139 --> 00:50:17.862 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>高彬死了，她跟男友分手</c>\n\nsrc-756\n00:50:17.976 --> 00:50:19.436 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>周游列国</c>\n\nsrc-757\n00:50:19.520 --> 00:50:22.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实现梦想</c>\n\nsrc-758\n00:50:22.481 --> 00:50:28.070 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她说受了我的话所启发</c>\n\nsrc-759\n00:50:28.153 --> 00:50:31.156 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们由寄明信片，进而通信</c>\n\nsrc-760\n00:50:31.240 --> 00:50:34.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>虽然相隔一方</c>\n\nsrc-761\n00:50:34.618 --> 00:50:36.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但依然是好朋友</c>\n\nsrc-762\n00:50:36.547 --> 00:50:38.132 align:middle line:85%,start position:50%,middle\n《简爱》\n\nsrc-763\n00:50:41.250 --> 00:50:44.555 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>1994年，纽约一片兴旺</c>\n\nsrc-764\n00:50:44.597 --> 00:50:46.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>空缺多，资金多</c>\n\nsrc-765\n00:50:46.171 --> 00:50:49.925 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>互联网上场\n眨眼间，曼哈顿街头</c>\n\nsrc-766\n00:50:50.008 --> 00:50:51.686 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>人手一机</c>\n\nsrc-767\n00:50:51.811 --> 00:50:53.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>处处用，不断用</c>\n\nsrc-768\n00:50:55.889 --> 00:50:58.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老板</c>\n\nsrc-769\n00:50:58.193 --> 00:50:59.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>州长选举　投罗伯度一票</c>\n\nsrc-770\n00:50:59.653 --> 00:51:01.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给我们初露头角的机会</c>\n\nsrc-771\n00:51:03.313 --> 00:51:07.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我终于进入决策室</c>\n\nsrc-772\n00:51:07.901 --> 00:51:09.069 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 加拉夫\n- 希斯</c>\n\nsrc-773\n00:51:09.152 --> 00:51:10.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>早上好</c>\n\nsrc-774\n00:51:10.612 --> 00:51:12.239 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会议开始</c>\n\nsrc-775\n00:51:12.990 --> 00:51:14.324 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>北部情况怎样？</c>\n\nsrc-776\n00:51:14.408 --> 00:51:18.287 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>初次在纽约应邀出席社交场合</c>\n\nsrc-777\n00:51:18.370 --> 00:51:19.454 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>咸顿新作：《七沦八落》</c>\n\nsrc-778\n00:51:19.538 --> 00:51:25.711 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最濒危的生物不是鸟，不是鱼</c>\n\nsrc-779\n00:51:25.794 --> 00:51:28.431 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而是我们的舌头！</c>\n\nsrc-780\n00:51:28.515 --> 00:51:32.050 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天的语言，乱七八糟</c>\n\nsrc-781\n00:51:32.134 --> 00:51:35.262 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>词汇只及一百年前三分之一</c>\n\nsrc-782\n00:51:35.345 --> 00:51:39.733 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>句子即用即弃</c>\n\nsrc-783\n00:51:39.850 --> 00:51:42.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>文字生态，惨遭砍伐</c>\n\nsrc-784\n00:51:42.978 --> 00:51:48.233 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>被涓涓不绝的流行文化蚕食丑化</c>\n\nsrc-785\n00:51:48.317 --> 00:51:49.827 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉</c>\n\nsrc-786\n00:51:53.822 --> 00:51:58.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜爱的小子\n你看来很有男子气</c>\n\nsrc-787\n00:51:58.619 --> 00:52:02.039 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过奖，我正希望这样</c>\n\nsrc-788\n00:52:02.831 --> 00:52:04.675 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉可好？</c>\n\nsrc-789\n00:52:06.376 --> 00:52:09.171 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉做了人家的日记的主角</c>\n\nsrc-790\n00:52:10.714 --> 00:52:14.968 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 教授怎样？\n- 教授好极</c>\n\nsrc-791\n00:52:15.052 --> 00:52:18.388 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他很惹笑\n- 他移情别恋，搭上二年级生</c>\n\nsrc-792\n00:52:19.223 --> 00:52:21.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说是为我着想</c>\n\nsrc-793\n00:52:22.518 --> 00:52:25.729 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>似乎潮流兴那种借口</c>\n\nsrc-794\n00:52:27.564 --> 00:52:29.525 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>近况怎样？</c>\n\nsrc-795\n00:52:30.567 --> 00:52:35.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在一家纽约杂志……\n做爬格子动物</c>\n\nsrc-796\n00:52:35.906 --> 00:52:37.699 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>静候时机</c>\n\nsrc-797\n00:52:37.783 --> 00:52:42.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“句法”可不是妓院向国税局交的“罪恶税”</c>\n\nsrc-798\n00:52:42.996 --> 00:52:45.048 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要走近去听</c>\n\nsrc-799\n00:52:45.624 --> 00:52:46.667 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>眼镜好看</c>\n\nsrc-800\n00:52:46.750 --> 00:52:49.378 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听听你下代的言语吧</c>\n\nsrc-801\n00:52:52.589 --> 00:52:55.175 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯！</c>\n\nsrc-802\n00:52:57.094 --> 00:52:59.388 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来自……不要告诉我！</c>\n\nsrc-803\n00:52:59.437 --> 00:53:02.641 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威斯康星州！对，奶酪之州</c>\n\nsrc-804\n00:53:04.768 --> 00:53:06.353 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你来参加我们的聚会</c>\n\nsrc-805\n00:53:06.436 --> 00:53:07.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再来，麻烦你</c>\n\nsrc-806\n00:53:08.063 --> 00:53:12.067 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏说你替罗伯度写演词</c>\n\nsrc-807\n00:53:12.150 --> 00:53:16.405 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她说你有个第二年级学生的女友\n- 其实是两个一年级学生</c>\n\nsrc-808\n00:53:16.488 --> 00:53:19.950 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>两个一年加起来等于一个二年</c>\n\nsrc-809\n00:53:21.201 --> 00:53:24.746 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>陪我走\n为什么替市侩佬罗伯度捉刀？</c>\n\nsrc-810\n00:53:24.830 --> 00:53:30.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你当初给我的印象……\n是有原则，甚至有理想</c>\n\nsrc-811\n00:53:31.128 --> 00:53:35.465 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不是沦为身穿雅曼尼的……\n优皮士吧？</c>\n\nsrc-812\n00:53:35.549 --> 00:53:39.219 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你很出色，他对你客气吧？</c>\n\nsrc-813\n00:53:39.303 --> 00:53:42.222 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他有能力自辩\n- 对，我有能力</c>\n\nsrc-814\n00:53:42.306 --> 00:53:45.851 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗伯度并不市侩，而是有实力</c>\n\nsrc-815\n00:53:45.934 --> 00:53:48.026 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当过差，办过企业</c>\n\nsrc-816\n00:53:48.478 --> 00:53:52.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他是脓包，正是我的书中人物</c>\n\nsrc-817\n00:53:52.149 --> 00:53:53.817 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>读读吧，免费</c>\n\nsrc-818\n00:53:54.985 --> 00:53:59.198 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真善美，已经不受重视</c>\n\nsrc-819\n00:53:59.281 --> 00:54:02.075 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 大家讲得都是财与势\n- 我读过你作品</c>\n\nsrc-820\n00:54:02.159 --> 00:54:04.203 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你重视财与势</c>\n\nsrc-821\n00:54:04.286 --> 00:54:06.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为他无财无势，对吗？</c>\n\nsrc-822\n00:54:06.747 --> 00:54:09.166 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只重情义</c>\n\nsrc-823\n00:54:09.756 --> 00:54:11.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以你亲近我……</c>\n\nsrc-824\n00:54:11.925 --> 00:54:15.672 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为了抑制你的勃勃野心</c>\n\nsrc-825\n00:54:17.257 --> 00:54:18.967 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有个提议</c>\n\nsrc-826\n00:54:19.468 --> 00:54:24.097 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你既然捞到一丁点影响力……</c>\n\nsrc-827\n00:54:24.181 --> 00:54:29.102 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不帮助……\n阿夏写一份报道罗伯度的文章？</c>\n\nsrc-828\n00:54:29.186 --> 00:54:32.189 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏有表现机会，你有宣传机会</c>\n\nsrc-829\n00:54:32.272 --> 00:54:34.566 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你呢？有什么好处？</c>\n\nsrc-830\n00:54:35.526 --> 00:54:39.988 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>散播情义，我是有情有义的人</c>\n\nsrc-831\n00:54:40.072 --> 00:54:41.281 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>情义</c>\n\nsrc-832\n00:54:41.365 --> 00:54:43.581 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 早知阿夏会再出现\n- 是吗？</c>\n\nsrc-833\n00:54:43.623 --> 00:54:45.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来不喜欢她，现在有点喜欢</c>\n\nsrc-834\n00:54:45.827 --> 00:54:49.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你和她约会过吗？</c>\n\nsrc-835\n00:54:49.540 --> 00:54:52.924 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不可以，因为她在写文章</c>\n\nsrc-836\n00:54:52.965 --> 00:54:56.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>民主党的罗伯度–铁腕灭罪</c>\n\nsrc-837\n00:55:14.439 --> 00:55:19.570 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 相当不错啊\n- 威廉，非常好</c>\n\nsrc-838\n00:55:25.117 --> 00:55:26.910 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是捧场文章？</c>\n\nsrc-839\n00:55:26.994 --> 00:55:29.496 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是，很精彩</c>\n\nsrc-840\n00:55:29.580 --> 00:55:33.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有部分我觉得不很妥</c>\n\nsrc-841\n00:55:34.001 --> 00:55:35.006 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯……</c>\n\nsrc-842\n00:55:35.048 --> 00:55:40.215 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗伯度的首席捉刀人……\n俊朗而认真，略带孩子气</c>\n\nsrc-843\n00:55:41.008 --> 00:55:42.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>孩子气？</c>\n\nsrc-844\n00:55:43.844 --> 00:55:45.762 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来是这样写……</c>\n\nsrc-845\n00:55:45.846 --> 00:55:49.349 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯眼波含情，令人……</c>\n\nsrc-846\n00:55:49.433 --> 00:55:51.643 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>恨不得立刻扒光他的衣服</c>\n\nsrc-847\n00:55:51.727 --> 00:55:54.563 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但主编要我修改</c>\n\nsrc-848\n00:55:54.646 --> 00:55:57.571 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>文人多大话</c>\n\nsrc-849\n00:55:58.859 --> 00:56:00.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你从小立志做记者？</c>\n\nsrc-850\n00:56:00.986 --> 00:56:05.908 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>小时想做女演员……\n到百老汇登台唱歌</c>\n\nsrc-851\n00:56:05.991 --> 00:56:07.534 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真的？</c>\n\nsrc-852\n00:56:07.618 --> 00:56:10.370 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你难以置信？</c>\n\nsrc-853\n00:56:10.454 --> 00:56:15.918 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>女演员多愁善感，需要呵护</c>\n\nsrc-854\n00:56:16.001 --> 00:56:19.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>意思是我冷漠？</c>\n\nsrc-855\n00:56:19.463 --> 00:56:21.173 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很需要呵护</c>\n\nsrc-856\n00:56:21.256 --> 00:56:23.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我意思是想听听你唱歌</c>\n\nsrc-857\n00:56:25.802 --> 00:56:27.763 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 什么？\n- 唱一首来听听</c>\n\nsrc-858\n00:56:28.805 --> 00:56:31.228 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 要我唱？\n- 怕什么？</c>\n\nsrc-859\n00:56:33.101 --> 00:56:35.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 有没有首本名曲？\n- 有</c>\n\nsrc-860\n00:56:35.646 --> 00:56:37.356 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有？</c>\n\nadd-release-donor-960\n00:56:40.192 --> 00:56:41.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧。</c>\n\nsrc-861\n00:56:43.904 --> 00:56:48.367 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不论是阿添、威廉……</c>\n\nsrc-862\n00:56:48.450 --> 00:56:52.704 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>倘若获得我垂青……</c>\n\nsrc-863\n00:56:52.788 --> 00:56:55.207 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我叫威廉\n- 不要打岔</c>\n\nsrc-864\n00:56:55.290 --> 00:56:57.501 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知多高兴</c>\n\nsrc-865\n00:56:58.085 --> 00:57:01.171 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过以你最情长</c>\n\nsrc-866\n00:57:01.255 --> 00:57:04.049 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我难再反抗</c>\n\nsrc-867\n00:57:04.132 --> 00:57:05.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只好投降</c>\n\nsrc-868\n00:57:07.094 --> 00:57:08.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>感觉多美妙</c>\n\nsrc-869\n00:57:12.101 --> 00:57:14.270 align:middle line:85%,start position:50%,middle\n不是因为你长得帅\n\nsrc-870\n00:57:15.352 --> 00:57:18.146 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>穿上去好不好？</c>\n\nsrc-871\n00:57:21.567 --> 00:57:23.777 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不太难看</c>\n\nsrc-872\n00:57:23.861 --> 00:57:26.530 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一千块一件，好搞笑</c>\n\nsrc-873\n00:57:28.615 --> 00:57:35.622 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我为你着迷，我的小甜心</c>\n\nsrc-874\n00:57:35.706 --> 00:57:37.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>法兰仙纳杜拉、琳达朗丝黛</c>\n\nsrc-875\n00:57:37.791 --> 00:57:39.042 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么？</c>\n\nsrc-876\n00:57:39.126 --> 00:57:44.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你看看背后，都有一首歌</c>\n\nsrc-877\n00:57:44.339 --> 00:57:46.803 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 《我为你着迷》\n- 张张都有</c>\n\nsrc-878\n00:57:48.135 --> 00:57:51.555 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 写得怎么样？\n- 还一个字都没写</c>\n\nsrc-879\n00:57:53.098 --> 00:57:55.100 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也是</c>\n\nsrc-880\n00:57:58.729 --> 00:58:00.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 差不多\n- 我也是</c>\n\nsrc-881\n00:58:00.772 --> 00:58:06.113 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家不会怪我傻……</c>\n\nsrc-882\n00:58:06.695 --> 00:58:13.702 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我……为你……着……</c>\n\nsrc-883\n00:58:40.395 --> 00:58:42.064 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有没有扯鼻鼾？</c>\n\nsrc-884\n00:58:49.154 --> 00:58:51.448 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有件事我从没试过</c>\n\nsrc-885\n00:58:54.827 --> 00:58:58.414 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>整天跟一个好男人躺在床上</c>\n\nsrc-886\n00:58:58.830 --> 00:59:00.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也没试过</c>\n\nsrc-887\n00:59:01.166 --> 00:59:03.377 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是认真</c>\n\nsrc-888\n00:59:03.460 --> 00:59:06.672 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总有更重要的事要办</c>\n\nsrc-889\n00:59:06.755 --> 00:59:08.674 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是工作狂</c>\n\nsrc-890\n00:59:10.092 --> 00:59:11.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常狂热</c>\n\nsrc-891\n00:59:16.014 --> 00:59:18.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你肯整天躺在床上陪我吗？</c>\n\nsrc-892\n00:59:20.227 --> 00:59:21.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么都不做</c>\n\nsrc-893\n00:59:39.872 --> 00:59:44.168 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是阿夏，请留言，我稍后回复</c>\n\nsrc-894\n00:59:44.251 --> 00:59:48.338 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是长老会医院急症室</c>\n\nsrc-895\n00:59:48.422 --> 00:59:50.757 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>急症室？</c>\n\nsrc-896\n00:59:50.841 --> 00:59:54.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 咸顿先生主动脉破裂\n- 即是什么？</c>\n\nsrc-897\n00:59:54.678 --> 00:59:57.389 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好像一部车，驶得太久、太快……</c>\n\nsrc-898\n00:59:57.472 --> 00:59:59.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>结果爆胎</c>\n\nsrc-899\n01:00:02.519 --> 01:00:05.147 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>咸顿先生，怎样？舒服吗？</c>\n\nsrc-900\n01:00:05.230 --> 01:00:07.274 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>输到不由不服</c>\n\nsrc-901\n01:00:09.359 --> 01:00:13.446 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>笑一笑吧，我为这个笑话绞尽脑汁</c>\n\nsrc-902\n01:00:15.365 --> 01:00:16.909 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怪可怜</c>\n\nsrc-903\n01:00:18.618 --> 01:00:20.412 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>夏日来临</c>\n\nsrc-904\n01:00:23.790 --> 01:00:26.293 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他来做什么？\n- 你好，咸顿</c>\n\nsrc-905\n01:00:26.376 --> 01:00:28.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好</c>\n\nsrc-906\n01:00:31.048 --> 01:00:33.300 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只有一处医生没有修理</c>\n\nsrc-907\n01:00:33.383 --> 01:00:35.844 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要提草根、同化</c>\n\nsrc-908\n01:00:36.887 --> 01:00:39.181 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你跟那小子交往，真要了我的命</c>\n\nsrc-909\n01:00:39.264 --> 01:00:43.852 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要你命的不是烟酒色？</c>\n\nsrc-910\n01:00:43.936 --> 01:00:46.813 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那些都不相干\n- 不相干</c>\n\nsrc-911\n01:00:46.897 --> 01:00:51.276 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我已经把器官捐作医学研究</c>\n\nsrc-912\n01:00:51.360 --> 01:00:53.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>除了一件，留给你</c>\n\nsrc-913\n01:00:54.571 --> 01:00:59.785 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真体贴\n- 不是那个</c>\n\nsrc-914\n01:00:59.868 --> 01:01:02.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我颗心呀，傻妹</c>\n\nsrc-915\n01:01:05.457 --> 01:01:08.669 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>告诉我，你没有爱上他</c>\n\nsrc-916\n01:01:08.752 --> 01:01:10.462 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不可以那样说</c>\n\nsrc-917\n01:01:14.299 --> 01:01:17.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以抽根烟吗？临终愿望</c>\n\nsrc-918\n01:01:17.928 --> 01:01:21.723 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不准抽烟，你总是夸张</c>\n\nsrc-919\n01:01:21.807 --> 01:01:23.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不会死</c>\n\nsrc-920\n01:01:25.936 --> 01:01:28.856 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱他，你应该无所谓</c>\n\nsrc-921\n01:01:28.939 --> 01:01:30.899 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是你撮合我们，记得吗？</c>\n\nsrc-922\n01:01:30.983 --> 01:01:33.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还以为你会把他吃干抹净就甩掉</c>\n\nsrc-923\n01:01:33.652 --> 01:01:37.281 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说话很得体</c>\n\nsrc-924\n01:01:38.323 --> 01:01:40.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那篇关于罗伯度的文章……</c>\n\nsrc-925\n01:01:43.537 --> 01:01:45.664 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他从政有二十多年……</c>\n\nsrc-926\n01:01:45.747 --> 01:01:50.335 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你只挖到他女儿饮食失调？</c>\n\nsrc-927\n01:01:50.836 --> 01:01:52.713 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在说什么？</c>\n\nsrc-928\n01:01:54.006 --> 01:01:55.799 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>尽你本份</c>\n\nsrc-929\n01:02:04.349 --> 01:02:05.390 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿支持罗伯度</c>\n\nsrc-930\n01:02:05.473 --> 01:02:07.517 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们会亲身见到总统</c>\n\nsrc-931\n01:02:07.853 --> 01:02:10.314 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看啊</c>\n\nsrc-932\n01:02:10.397 --> 01:02:12.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今时不同往日，我们不再是跑腿</c>\n\nsrc-933\n01:02:12.983 --> 01:02:14.401 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常感谢</c>\n\nsrc-934\n01:02:14.484 --> 01:02:16.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>离谱！</c>\n\nsrc-935\n01:02:17.070 --> 01:02:19.823 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>竟然没有人检查过菜单</c>\n\nsrc-936\n01:02:19.907 --> 01:02:22.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上面没有印上工会徽章</c>\n\nsrc-937\n01:02:22.824 --> 01:02:26.246 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>外面有人示威，没有人进得来</c>\n\nsrc-938\n01:02:26.330 --> 01:02:28.165 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>表演嘉宾卡恩呢？</c>\n\nsrc-939\n01:02:28.248 --> 01:02:31.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大概饮醉酒</c>\n\nsrc-940\n01:02:31.335 --> 01:02:32.836 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天晓得他在哪里？</c>\n\nsrc-941\n01:02:32.920 --> 01:02:35.297 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下冰雹</c>\n\nsrc-942\n01:02:35.380 --> 01:02:36.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>又关我们事？</c>\n\nsrc-943\n01:02:36.632 --> 01:02:38.800 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总统从芝加哥搭机来</c>\n\nsrc-944\n01:02:38.884 --> 01:02:40.469 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要担心</c>\n\nsrc-945\n01:02:40.552 --> 01:02:44.973 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你太粗心大意，连徽章也未印！</c>\n\nsrc-946\n01:02:45.057 --> 01:02:47.014 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂！</c>\n\nsrc-947\n01:02:47.097 --> 01:02:50.979 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>深呼吸，好不好？</c>\n\nsrc-948\n01:02:51.063 --> 01:02:52.981 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以使用酒店的上网与打印设施</c>\n\nsrc-949\n01:02:53.065 --> 01:02:54.483 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会连络卡恩的经理人</c>\n\nsrc-950\n01:02:54.566 --> 01:02:55.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喝杯酒定定神</c>\n\nsrc-951\n01:02:55.984 --> 01:02:58.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不识你，但你未拉拉链</c>\n\nsrc-952\n01:02:58.820 --> 01:03:01.365 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>记住着底裤，我去看天气报告</c>\n\nsrc-953\n01:03:01.448 --> 01:03:07.079 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>七号桌上菜：六份意面、两份鱼！</c>\n\nsrc-954\n01:03:09.122 --> 01:03:10.624 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他不是工会会员</c>\n\nsrc-955\n01:03:10.707 --> 01:03:13.293 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是美国总统</c>\n\nsrc-956\n01:03:13.377 --> 01:03:16.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>叫你们示威者不要阻塞通道</c>\n\nsrc-957\n01:03:16.505 --> 01:03:19.132 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不可以对工会那样说话！</c>\n\nsrc-958\n01:03:19.216 --> 01:03:21.797 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 可是他……\n- 不要担心</c>\n\nsrc-959\n01:03:21.881 --> 01:03:23.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我上网下载了工会徽章</c>\n\nsrc-960\n01:03:23.341 --> 01:03:25.013 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>贴在菜单上，复印五百份</c>\n\nsrc-961\n01:03:25.097 --> 01:03:28.141 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>找家工会印刷店来印，问题就解决了</c>\n\nsrc-962\n01:03:28.225 --> 01:03:30.143 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要我去复印？</c>\n\nsrc-963\n01:03:32.855 --> 01:03:35.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们都做过复印，现在你做</c>\n\nsrc-964\n01:03:35.566 --> 01:03:37.609 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一点都不好笑，海斯，太……</c>\n\nsrc-965\n01:03:37.693 --> 01:03:40.028 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>认真成熟，你去哪里？</c>\n\nsrc-966\n01:03:40.112 --> 01:03:42.276 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很忙！半小时回来</c>\n\nsrc-967\n01:03:42.318 --> 01:03:43.866 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>混蛋</c>\n\nsrc-968\n01:03:46.743 --> 01:03:48.120 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯？</c>\n\nsrc-969\n01:03:48.203 --> 01:03:49.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我</c>\n\nsrc-970\n01:03:49.492 --> 01:03:52.082 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在盯着你</c>\n\nsrc-971\n01:03:52.165 --> 01:03:55.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我已经把你们的老底查了个底朝天</c>\n\nsrc-972\n01:03:55.502 --> 01:03:58.751 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爆料的话，你们就玩完</c>\n\nsrc-973\n01:03:58.835 --> 01:04:00.461 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\nsrc-974\n01:04:01.550 --> 01:04:05.137 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你是谁？\n- 见面就知</c>\n\nsrc-975\n01:04:05.846 --> 01:04:08.098 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你在哪里？\n- 附近</c>\n\nsrc-976\n01:04:09.099 --> 01:04:13.604 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我从未遇过……这种情形</c>\n\nsrc-977\n01:04:14.350 --> 01:04:16.059 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你接近了</c>\n\nsrc-978\n01:04:17.686 --> 01:04:19.354 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常接近</c>\n\nsrc-979\n01:04:19.896 --> 01:04:21.398 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常接近</c>\n\nsrc-980\n01:04:21.481 --> 01:04:23.989 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>近在眼前！</c>\n\nsrc-981\n01:04:26.491 --> 01:04:28.113 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>骗到你！</c>\n\nsrc-982\n01:04:29.119 --> 01:04:30.662 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还以为你出国避暑</c>\n\nsrc-983\n01:04:30.746 --> 01:04:33.874 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来出了国，但发生了件奇事</c>\n\nsrc-984\n01:04:33.957 --> 01:04:37.085 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在希腊克里特岛的沙滩上……</c>\n\nsrc-985\n01:04:37.169 --> 01:04:40.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>结识了个叫柏高的男人</c>\n\nsrc-986\n01:04:40.797 --> 01:04:44.176 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他深沉又性感，沉默寡言，完全是我喜欢的类型</c>\n\nsrc-987\n01:04:44.259 --> 01:04:47.137 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有一晚，柏高拥吻我</c>\n\nsrc-988\n01:04:47.221 --> 01:04:49.806 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 吻得火热\n- 细节不必交代</c>\n\nsrc-989\n01:04:49.890 --> 01:04:52.309 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我有什么反应？\n- 不知道</c>\n\nsrc-990\n01:04:52.392 --> 01:04:53.644 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我哭起来</c>\n\nsrc-991\n01:04:53.727 --> 01:04:56.146 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>眼泪直流</c>\n\nsrc-992\n01:04:56.230 --> 01:04:59.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他没有察觉，因为忙着上下其手</c>\n\nsrc-993\n01:04:59.775 --> 01:05:03.946 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我愈发伤心</c>\n\nsrc-994\n01:05:04.029 --> 01:05:07.741 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我预见到这段感情会怎样发展</c>\n\nsrc-995\n01:05:07.824 --> 01:05:12.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>初时，柏高必然对我无限爱慕……</c>\n\nsrc-996\n01:05:13.163 --> 01:05:16.291 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我们来做什么？\n- 取物件</c>\n\nsrc-997\n01:05:16.375 --> 01:05:19.253 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但无论如何，只会落得同样收场</c>\n\nsrc-998\n01:05:20.712 --> 01:05:23.257 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>无可避免的收场</c>\n\nsrc-999\n01:05:23.340 --> 01:05:25.592 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就是他不再爱我</c>\n\nsrc-1000\n01:05:25.676 --> 01:05:27.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他翻爱为恨，伤我心</c>\n\nsrc-1001\n01:05:28.428 --> 01:05:30.222 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>虽然事后他会后悔</c>\n\nsrc-1002\n01:05:30.305 --> 01:05:32.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>于是……</c>\n\nsrc-1003\n01:05:32.266 --> 01:05:36.096 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我从他的温柔嘴唇挣开……</c>\n\nsrc-1004\n01:05:36.138 --> 01:05:38.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>把他手从我屁股移走！</c>\n\nsrc-1005\n01:05:40.524 --> 01:05:44.152 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 掉头就走\n- 走得好</c>\n\nsrc-1006\n01:05:44.236 --> 01:05:49.616 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我竟然离开万人迷柏高</c>\n\nsrc-1007\n01:05:49.700 --> 01:05:51.952 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是非同小可的决定</c>\n\nsrc-1008\n01:05:52.035 --> 01:05:54.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想找人倾诉</c>\n\nsrc-1009\n01:05:54.371 --> 01:05:56.415 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想找谁？</c>\n\nsrc-1010\n01:05:56.498 --> 01:05:58.458 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>原来我想找一个……</c>\n\nsrc-1011\n01:05:58.542 --> 01:06:03.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>远在天边近在眼前的人</c>\n\nsrc-1012\n01:06:03.547 --> 01:06:05.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么东西？</c>\n\nsrc-1013\n01:06:06.925 --> 01:06:09.128 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也有消息告诉你</c>\n\nsrc-1014\n01:06:14.266 --> 01:06:16.518 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么那样生气？</c>\n\nsrc-1015\n01:06:16.602 --> 01:06:19.646 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们通信那样久</c>\n\nsrc-1016\n01:06:19.730 --> 01:06:21.648 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你却不早说……</c>\n\nsrc-1017\n01:06:21.732 --> 01:06:26.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>第一：你有意中人，第二……\n你有意中人</c>\n\nsrc-1018\n01:06:26.528 --> 01:06:28.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我说过我有女友\n- 女友？</c>\n\nsrc-1019\n01:06:28.113 --> 01:06:30.775 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你刚买订婚戒指啊！</c>\n\nsrc-1020\n01:06:30.817 --> 01:06:33.076 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我太紧张，没有告诉你</c>\n\nsrc-1021\n01:06:33.160 --> 01:06:35.704 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么？</c>\n\nsrc-1022\n01:06:37.414 --> 01:06:39.082 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道</c>\n\nsrc-1023\n01:06:39.583 --> 01:06:41.627 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很爱这女子</c>\n\nsrc-1024\n01:06:42.920 --> 01:06:45.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我希望你为我高兴</c>\n\nsrc-1025\n01:06:46.924 --> 01:06:50.594 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我可以为你高兴，当然可以</c>\n\nsrc-1026\n01:06:54.306 --> 01:06:55.891 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可怜的爱珮</c>\n\nsrc-1027\n01:06:55.974 --> 01:06:59.394 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她一向做你朋友，后来发现……</c>\n\nsrc-1028\n01:06:59.478 --> 01:07:02.523 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不想做你朋友</c>\n\nsrc-1029\n01:07:02.606 --> 01:07:05.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想做你女友，可惜太迟</c>\n\nsrc-1030\n01:07:05.651 --> 01:07:07.069 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么意思？</c>\n\nsrc-1031\n01:07:07.152 --> 01:07:10.280 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你听不出吗？她回来是为了你</c>\n\nsrc-1032\n01:07:15.702 --> 01:07:18.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所有菜单都贴上了工会徽章</c>\n\nsrc-1033\n01:07:18.580 --> 01:07:22.201 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>芝加哥转晴，总统会八点到</c>\n\nsrc-1034\n01:07:22.242 --> 01:07:23.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>罗素呢？</c>\n\nsrc-1035\n01:07:23.544 --> 01:07:25.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他会去餐厅等你</c>\n\nsrc-1036\n01:07:25.287 --> 01:07:27.247 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在这里比较诙谐</c>\n\nsrc-1037\n01:07:28.957 --> 01:07:31.168 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的腿停不下来！</c>\n\nsrc-1038\n01:07:37.508 --> 01:07:39.218 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你来得早</c>\n\nsrc-1039\n01:07:44.598 --> 01:07:46.191 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>见到你真好</c>\n\nsrc-1040\n01:07:46.275 --> 01:07:48.068 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好看\n- 你也是</c>\n\nsrc-1041\n01:07:48.151 --> 01:07:51.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不错的领带\n- 是你挑选</c>\n\nsrc-1042\n01:07:52.322 --> 01:07:56.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>杂志叫我继续报道罗伯度</c>\n\nsrc-1043\n01:07:56.493 --> 01:07:59.329 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好啊\n- 是好，不过……</c>\n\nsrc-1044\n01:08:00.414 --> 01:08:02.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>复杂</c>\n\nsrc-1045\n01:08:03.625 --> 01:08:05.752 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你读吧</c>\n\nsrc-1046\n01:08:05.836 --> 01:08:07.620 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你已经写好</c>\n\nsrc-1047\n01:08:16.846 --> 01:08:19.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 他做过？\n- 是</c>\n\nsrc-1048\n01:08:19.224 --> 01:08:23.604 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他运用人事……令朋友提早出狱</c>\n\nsrc-1049\n01:08:23.687 --> 01:08:28.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很久以前的事，民意上……</c>\n\nsrc-1050\n01:08:28.442 --> 01:08:30.359 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们遥遥领先</c>\n\nsrc-1051\n01:08:30.444 --> 01:08:35.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使很久以前……\n但他的招牌是『铁腕灭罪』</c>\n\nsrc-1052\n01:08:37.201 --> 01:08:39.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大家读到……</c>\n\nsrc-1053\n01:08:41.622 --> 01:08:43.916 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏，听我说</c>\n\nsrc-1054\n01:08:43.999 --> 01:08:46.992 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你交稿，我们完蛋</c>\n\nsrc-1055\n01:08:47.127 --> 01:08:49.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是今期的重点文章</c>\n\nsrc-1056\n01:08:49.786 --> 01:08:52.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我指你同我</c>\n\nsrc-1057\n01:08:53.591 --> 01:08:58.128 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>『参选人被撰稿人女友拉下台』</c>\n\nsrc-1058\n01:08:58.210 --> 01:09:00.172 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只是恪尽本份</c>\n\nsrc-1059\n01:09:00.890 --> 01:09:03.435 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>第一篇稿我没有这样写</c>\n\nsrc-1060\n01:09:03.519 --> 01:09:06.729 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不写，人家会写</c>\n\nsrc-1061\n01:09:08.023 --> 01:09:09.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让人家去写</c>\n\nsrc-1062\n01:09:09.691 --> 01:09:12.069 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要交稿，好不好？</c>\n\nsrc-1063\n01:09:17.823 --> 01:09:19.648 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你已经交稿</c>\n\nadd-release-donor-1183\n01:09:35.759 --> 01:09:37.094 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>亚瑟先生……</c>\n\nsrc-1064\n01:09:40.639 --> 01:09:42.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢阿夏</c>\n\nsrc-1065\n01:09:42.224 --> 01:09:44.059 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想不到她是……</c>\n\nsrc-1066\n01:09:44.142 --> 01:09:45.352 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 狠心的人？\n- 不是</c>\n\nsrc-1067\n01:09:45.435 --> 01:09:47.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>投机者？反骨……</c>\n\nsrc-1068\n01:09:47.770 --> 01:09:49.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 坏女人！\n- 玛雅！</c>\n\nsrc-1069\n01:09:49.773 --> 01:09:51.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她怎可以这样对你？</c>\n\nsrc-1070\n01:09:51.692 --> 01:09:55.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>正如她说，她不写，人家写</c>\n\nsrc-1071\n01:09:55.362 --> 01:09:56.864 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是事实</c>\n\nsrc-1072\n01:09:56.947 --> 01:09:59.283 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么，她有没有伤你？</c>\n\nsrc-1073\n01:09:59.366 --> 01:10:01.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>伤我什么？</c>\n\nsrc-1074\n01:10:06.790 --> 01:10:08.792 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>文章登出怎样？</c>\n\nsrc-1075\n01:10:08.876 --> 01:10:12.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>《每日新闻》：退选！</c>\n\nsrc-1076\n01:10:24.808 --> 01:10:28.270 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你搞砸了，彻底搞砸了</c>\n\nsrc-1077\n01:10:28.353 --> 01:10:30.230 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不劳烦教训</c>\n\nsrc-1078\n01:10:30.314 --> 01:10:33.429 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想通会写信给你</c>\n\nsrc-1079\n01:10:33.513 --> 01:10:34.889 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拭目以待</c>\n\nsrc-1080\n01:10:35.027 --> 01:10:40.157 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>于是，失去女友\n失去工作，失去朋友</c>\n\nsrc-1081\n01:10:41.116 --> 01:10:44.828 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大受打击，心灰意冷</c>\n\nsrc-1082\n01:10:45.579 --> 01:10:47.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我不是唯一惹上麻烦的人</c>\n\nsrc-1083\n01:10:47.831 --> 01:10:52.753 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我跟她没有发生关系，我和……</c>\n\nsrc-1084\n01:10:52.836 --> 01:10:54.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>莱温斯基小姐</c>\n\nsrc-1085\n01:10:54.505 --> 01:10:56.507 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有叫人说谎</c>\n\nsrc-1086\n01:10:56.590 --> 01:10:58.133 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有没有看？</c>\n\nsrc-1087\n01:10:58.217 --> 01:11:00.344 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>指控是没有根据</c>\n\nsrc-1088\n01:11:00.427 --> 01:11:01.386 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱珮？</c>\n\nsrc-1089\n01:11:01.470 --> 01:11:05.599 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还会是谁？有没有看？</c>\n\nsrc-1090\n01:11:05.682 --> 01:11:07.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当然在看</c>\n\nsrc-1091\n01:11:08.685 --> 01:11:09.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你认为他做过？</c>\n\nsrc-1092\n01:11:10.062 --> 01:11:14.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道他做过，看她照片吧……\n我也动心</c>\n\nsrc-1093\n01:11:14.733 --> 01:11:16.777 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她很合他胃口</c>\n\nsrc-1094\n01:11:18.904 --> 01:11:21.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样久才打来</c>\n\nsrc-1095\n01:11:22.032 --> 01:11:23.700 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还以为你不睬我</c>\n\nsrc-1096\n01:11:23.784 --> 01:11:27.663 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好像没有打给我很多年\n- 现在不是打给你吗？</c>\n\nsrc-1097\n01:11:30.415 --> 01:11:32.835 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎样？近况如何？</c>\n\nsrc-1098\n01:11:32.918 --> 01:11:35.032 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有新室友……奥莉维亚</c>\n\nsrc-1099\n01:11:36.213 --> 01:11:37.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在书店工作</c>\n\nsrc-1100\n01:11:37.576 --> 01:11:38.702 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>芭芭拉 贝加藏书</c>\n\nsrc-1101\n01:11:38.841 --> 01:11:41.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想重返校园</c>\n\nsrc-1102\n01:11:41.218 --> 01:11:44.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我厌倦这份工，以前喜欢</c>\n\nsrc-1103\n01:11:44.304 --> 01:11:46.752 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在觉得自己是文贩</c>\n\nsrc-1104\n01:11:46.793 --> 01:11:48.433 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这本二手《简爱》没有题词</c>\n\nsrc-1105\n01:11:48.517 --> 01:11:50.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在和别人交往吗？</c>\n\nsrc-1106\n01:11:50.797 --> 01:11:54.648 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿当选以来我没有性生活</c>\n\nsrc-1107\n01:11:54.731 --> 01:11:55.774 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>请继续寻找</c>\n\nsrc-1108\n01:11:55.858 --> 01:11:56.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>蒙妮卡的裙子！</c>\n\nsrc-1109\n01:11:56.970 --> 01:11:58.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他的性生活多姿多采</c>\n\nsrc-1110\n01:11:58.944 --> 01:12:00.891 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要苛责</c>\n\nsrc-1111\n01:12:01.029 --> 01:12:04.324 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你应该向他学习，勾引见习生</c>\n\nsrc-1112\n01:12:04.408 --> 01:12:06.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真巧，我们来了个娇俏女见习</c>\n\nsrc-1113\n01:12:06.743 --> 01:12:10.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上工才一个星期</c>\n\nsrc-1114\n01:12:10.581 --> 01:12:12.499 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约她出去吧</c>\n\nsrc-1115\n01:12:13.250 --> 01:12:15.085 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者应该约</c>\n\nsrc-1116\n01:12:16.086 --> 01:12:19.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我不会约，我不想随便</c>\n\nsrc-1117\n01:12:19.840 --> 01:12:21.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想认真</c>\n\nsrc-1118\n01:12:21.842 --> 01:12:25.387 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>假以时日，才能认真</c>\n\nsrc-1119\n01:12:25.470 --> 01:12:28.599 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么意思？</c>\n\nsrc-1120\n01:12:28.682 --> 01:12:31.894 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>活到一定年纪，才能定性</c>\n\nsrc-1121\n01:12:31.977 --> 01:12:35.230 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>定性后，才想生儿育女……</c>\n\nsrc-1122\n01:12:35.314 --> 01:12:36.690 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>贷款置家</c>\n\nsrc-1123\n01:12:36.773 --> 01:12:38.511 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们有台了</c>\n\nsrc-1124\n01:12:38.901 --> 01:12:43.155 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>到时，你同配偶会二人同心</c>\n\nsrc-1125\n01:12:43.238 --> 01:12:45.991 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你指是时日问题</c>\n\nsrc-1126\n01:12:46.074 --> 01:12:47.784 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对极</c>\n\nsrc-1127\n01:12:47.868 --> 01:12:51.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么，你还未遇到……</c>\n\nsrc-1128\n01:12:51.997 --> 01:12:53.916 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的真命天子？</c>\n\nsrc-1129\n01:12:54.458 --> 01:12:55.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还未</c>\n\nsrc-1130\n01:12:56.376 --> 01:12:59.379 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不风流快乐？</c>\n\nsrc-1131\n01:12:59.463 --> 01:13:00.658 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我正在</c>\n\nsrc-1132\n01:13:00.700 --> 01:13:02.633 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>正在？</c>\n\nsrc-1133\n01:13:03.425 --> 01:13:05.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有个叫奇云的男友</c>\n\nsrc-1134\n01:13:06.247 --> 01:13:08.055 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇云</c>\n\nsrc-1135\n01:13:08.138 --> 01:13:09.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是什么家伙？</c>\n\nsrc-1136\n01:13:09.389 --> 01:13:12.726 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么没有提起？</c>\n\nsrc-1137\n01:13:12.809 --> 01:13:14.728 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在提起了</c>\n\nsrc-1138\n01:13:15.547 --> 01:13:18.649 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱喝鲜薄荷茶</c>\n\nsrc-1139\n01:13:18.732 --> 01:13:20.317 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱灌啤酒</c>\n\nsrc-1140\n01:13:20.400 --> 01:13:24.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那就视乎何谓『是』</c>\n\nsrc-1141\n01:13:24.738 --> 01:13:30.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果『是』即是『没有』……\n那就符合事实</c>\n\nsrc-1142\n01:13:37.027 --> 01:13:38.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是爱珮呀</c>\n\nsrc-1143\n01:13:38.585 --> 01:13:41.406 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你就快生日，打给我</c>\n\nsrc-1144\n01:13:42.881 --> 01:13:46.870 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂？希望打对电话，似乎是你</c>\n\nsrc-1145\n01:13:46.912 --> 01:13:48.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是艾美莉呀！</c>\n\nsrc-1146\n01:13:50.055 --> 01:13:52.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在纽约，我想……</c>\n\nsrc-1147\n01:13:52.850 --> 01:13:56.144 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约你喝咖啡，聚聚旧</c>\n\nsrc-1148\n01:13:56.588 --> 01:13:58.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的电话号码是……</c>\n\nsrc-1149\n01:13:59.857 --> 01:14:03.777 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是爱珮，我想跟你谈谈，覆我</c>\n\nsrc-1150\n01:14:03.861 --> 01:14:05.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>否则不客气</c>\n\nsrc-1151\n01:14:08.574 --> 01:14:11.076 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来了！</c>\n\nsrc-1152\n01:14:12.077 --> 01:14:13.912 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>搞错，来了</c>\n\nsrc-1153\n01:14:14.997 --> 01:14:16.623 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听到了</c>\n\nsrc-1154\n01:14:20.169 --> 01:14:22.129 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在做什么？</c>\n\nsrc-1155\n01:14:22.880 --> 01:14:25.048 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你打算打扮成这模样？</c>\n\nsrc-1156\n01:14:25.132 --> 01:14:28.468 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的生日会，人人恭候大驾</c>\n\nsrc-1157\n01:14:28.552 --> 01:14:29.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>惨</c>\n\nsrc-1158\n01:14:29.928 --> 01:14:32.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>五分钟，好吗？</c>\n\nsrc-1159\n01:14:34.808 --> 01:14:36.727 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我绊倒\n- 没事吧？</c>\n\nsrc-1160\n01:14:36.810 --> 01:14:39.313 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没事，我要躺一会</c>\n\nsrc-1161\n01:14:41.023 --> 01:14:43.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看得出你在吃面</c>\n\nsrc-1162\n01:14:46.904 --> 01:14:48.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>各位，他来了！</c>\n\nadd-release-donor-1286\n01:14:54.536 --> 01:14:55.537 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢。</c>\n\nadd-release-donor-1287\n01:14:56.914 --> 01:14:57.915 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好。</c>\n\nsrc-1163\n01:15:00.918 --> 01:15:03.879 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吓！想不到你们会来！</c>\n\nsrc-1164\n01:15:03.962 --> 01:15:06.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们专程从华盛顿而来</c>\n\nsrc-1165\n01:15:06.340 --> 01:15:08.091 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>生日快乐，帅哥</c>\n\nsrc-1166\n01:15:08.675 --> 01:15:10.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好一个美女</c>\n\nsrc-1167\n01:15:10.969 --> 01:15:12.596 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你走宝</c>\n\nsrc-1168\n01:15:12.679 --> 01:15:14.014 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希斯</c>\n\nsrc-1169\n01:15:19.335 --> 01:15:20.920 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过来</c>\n\nsrc-1170\n01:15:23.607 --> 01:15:26.902 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 见到你真好\n- 你看来……</c>\n\nsrc-1171\n01:15:26.985 --> 01:15:28.612 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>像流浪汉</c>\n\nsrc-1172\n01:15:29.655 --> 01:15:32.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嘉莉呢？\n- 那处</c>\n\nsrc-1173\n01:15:32.199 --> 01:15:35.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>宝宝出生以来，这是她第一次出来玩</c>\n\nsrc-1174\n01:15:36.186 --> 01:15:37.854 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>恭喜恭喜</c>\n\nsrc-1175\n01:15:39.122 --> 01:15:42.751 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>里根拿武器换石油，没问题</c>\n\nsrc-1176\n01:15:42.835 --> 01:15:46.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>克林顿得些口舌服务，就要弹劾</c>\n\nsrc-1177\n01:15:47.506 --> 01:15:50.300 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不要谈政治！\n- 或者应该弹劾他</c>\n\nsrc-1178\n01:15:50.384 --> 01:15:52.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>哗！为什么那样说？</c>\n\nsrc-1179\n01:15:52.970 --> 01:15:55.931 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不弹劾？我们信赖过他</c>\n\nsrc-1180\n01:15:56.014 --> 01:15:57.683 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>以为他不同流合污</c>\n\nsrc-1181\n01:15:57.766 --> 01:16:00.519 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但他连『是』字也说不清</c>\n\nsrc-1182\n01:16:01.478 --> 01:16:05.023 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>更加不要奢望他谈『真相』了</c>\n\nsrc-1183\n01:16:05.858 --> 01:16:08.217 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我会再投他票\n- 毫不迟疑</c>\n\nsrc-1184\n01:16:12.114 --> 01:16:13.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威尔这人真有意思</c>\n\nsrc-1185\n01:16:13.574 --> 01:16:16.141 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊，不如放满浴缸，再扔个烤面包机进去</c>\n\nsrc-1186\n01:16:19.955 --> 01:16:25.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝你生日快乐</c>\n\nsrc-1187\n01:16:25.502 --> 01:16:30.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝你生日快乐</c>\n\nsrc-1188\n01:16:30.674 --> 01:16:34.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝你生日快乐</c>\n\nsrc-1189\n01:16:34.511 --> 01:16:38.724 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 威廉呢？\n- 不知道，刚才还在这里</c>\n\nsrc-1190\n01:16:56.450 --> 01:16:58.307 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你错过了生日蛋糕</c>\n\nsrc-1191\n01:16:59.411 --> 01:17:01.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是我焗的\n- 是你焗的</c>\n\nsrc-1192\n01:17:04.666 --> 01:17:06.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>记得那首歌吗？</c>\n\nsrc-1193\n01:17:06.543 --> 01:17:08.212 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在你家里听过</c>\n\nsrc-1194\n01:17:08.795 --> 01:17:12.466 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>以朋友身份，你来找我</c>\n\nsrc-1195\n01:17:12.549 --> 01:17:14.843 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>似乎怀有敌意</c>\n\nsrc-1196\n01:17:14.927 --> 01:17:18.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是『似乎怀着回忆』\n- 我知</c>\n\nsrc-1197\n01:17:19.556 --> 01:17:23.143 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 有人多饮了几杯\n- 我没有</c>\n\nsrc-1198\n01:17:23.227 --> 01:17:24.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有</c>\n\nsrc-1199\n01:17:25.062 --> 01:17:26.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有</c>\n\nsrc-1200\n01:17:33.278 --> 01:17:36.156 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好美丽\n- 谢谢</c>\n\nsrc-1201\n01:17:40.077 --> 01:17:41.726 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么事？</c>\n\nsrc-1202\n01:17:43.288 --> 01:17:44.831 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>事实是……</c>\n\nsrc-1203\n01:17:45.749 --> 01:17:47.584 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>事实是……</c>\n\nsrc-1204\n01:17:48.877 --> 01:17:50.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢你</c>\n\nsrc-1205\n01:17:53.757 --> 01:17:55.592 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一向喜欢你</c>\n\nsrc-1206\n01:17:58.595 --> 01:18:00.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说『喜欢』……</c>\n\nsrc-1207\n01:18:00.848 --> 01:18:03.350 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太怯弱，太细胆</c>\n\nsrc-1208\n01:18:05.811 --> 01:18:07.437 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过说『爱』的话</c>\n\nsrc-1209\n01:18:07.521 --> 01:18:10.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会吓走你</c>\n\nsrc-1210\n01:18:12.860 --> 01:18:14.403 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱你</c>\n\nsrc-1211\n01:18:18.115 --> 01:18:20.242 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我爱上你，爱珮</c>\n\nsrc-1212\n01:18:28.125 --> 01:18:31.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为什么不早告诉我？\n- 还问？</c>\n\nsrc-1213\n01:18:31.795 --> 01:18:35.966 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你一向对我没兴趣</c>\n\nsrc-1214\n01:18:36.675 --> 01:18:38.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是蠢材</c>\n\nsrc-1215\n01:18:47.769 --> 01:18:49.271 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不行</c>\n\nsrc-1216\n01:18:49.354 --> 01:18:52.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不可以这样\n- 不可以怎样？</c>\n\nsrc-1217\n01:18:52.149 --> 01:18:54.484 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看你憔悴消极……</c>\n\nsrc-1218\n01:18:54.568 --> 01:18:57.613 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么不积极时候告诉我？</c>\n\nsrc-1219\n01:18:57.696 --> 01:19:00.616 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我积极\n- 你消极</c>\n\nsrc-1220\n01:19:01.950 --> 01:19:03.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你消极</c>\n\nsrc-1221\n01:19:06.288 --> 01:19:08.123 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我消极？</c>\n\nsrc-1222\n01:19:09.291 --> 01:19:12.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>出自你的口，倒也奇怪</c>\n\nsrc-1223\n01:19:14.338 --> 01:19:19.051 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你大有作为，却在书店工作</c>\n\nsrc-1224\n01:19:19.134 --> 01:19:21.345 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么回事？</c>\n\nsrc-1225\n01:19:22.346 --> 01:19:24.890 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>起码我曾经尝试，努力尝试</c>\n\nsrc-1226\n01:19:26.517 --> 01:19:30.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我这样说你，是出于一番善意</c>\n\nsrc-1227\n01:19:31.104 --> 01:19:34.525 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者你应该寻求辅导</c>\n\nsrc-1228\n01:19:34.608 --> 01:19:36.693 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>入人生康复所之类……</c>\n\nsrc-1229\n01:19:36.777 --> 01:19:39.446 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有那种机构的话……</c>\n\nsrc-1230\n01:19:39.530 --> 01:19:42.157 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对你会适合不过</c>\n\nsrc-1231\n01:19:42.241 --> 01:19:44.554 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我应该入『人生康复所』？</c>\n\nsrc-1232\n01:19:48.497 --> 01:19:50.374 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要坐在我门口！</c>\n\nsrc-1233\n01:19:51.917 --> 01:19:53.521 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱珮？</c>\n\nsrc-1234\n01:20:17.192 --> 01:20:18.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说得对</c>\n\nsrc-1235\n01:20:21.154 --> 01:20:23.907 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>的确复杂</c>\n\nsrc-1236\n01:20:23.991 --> 01:20:28.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你爱爱珮，爱珮本来爱卢卡斯……</c>\n\nsrc-1237\n01:20:28.579 --> 01:20:31.123 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>后来爱你，但你当时爱阿夏</c>\n\nsrc-1238\n01:20:31.206 --> 01:20:33.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而阿夏一直爱咸顿</c>\n\nsrc-1239\n01:20:33.959 --> 01:20:37.588 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在你爱爱珮，她却爱奇云</c>\n\nsrc-1240\n01:20:38.505 --> 01:20:40.674 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>结果谁也不爱你</c>\n\nsrc-1241\n01:20:41.717 --> 01:20:43.594 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>复杂啊</c>\n\nsrc-1242\n01:20:44.928 --> 01:20:46.406 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对</c>\n\nsrc-1243\n01:20:47.139 --> 01:20:48.891 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟着怎样？</c>\n\nsrc-1244\n01:21:06.510 --> 01:21:08.679 align:middle line:85%,start position:50%,middle\n《简爱》–夏洛蒂 勃朗特作\n\nsrc-1245\n01:21:08.785 --> 01:21:11.830 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>《简爱》，蓝灯书屋出版1943年</c>\n\nsrc-1246\n01:21:11.914 --> 01:21:16.084 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>优美的版本，特点是封面设计</c>\n\nsrc-1247\n01:21:16.168 --> 01:21:20.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>内有引用书中句语的动人题词</c>\n\nsrc-1248\n01:21:20.422 --> 01:21:24.218 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>致我亲爱的女儿阿普丽尔：人心深处藏有宝藏</c>\n\nsrc-1249\n01:21:24.301 --> 01:21:27.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>密密隐藏，默默封存</c>\n\nsrc-1250\n01:21:27.179 --> 01:21:29.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>思想、期望、美梦、喜爱……</c>\n\nsrc-1251\n01:21:29.681 --> 01:21:32.434 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一旦公开，魅力消散</c>\n\nsrc-1252\n01:21:33.143 --> 01:21:35.145 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>父亲题</c>\n\nsrc-1253\n01:21:45.489 --> 01:21:47.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 奥莉维亚\n- 威廉</c>\n\nsrc-1254\n01:21:48.283 --> 01:21:49.510 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 近况怎样？\n- 好啊</c>\n\nsrc-1255\n01:21:49.552 --> 01:21:52.120 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最近没听到你连声道歉的留言</c>\n\nsrc-1256\n01:21:52.204 --> 01:21:54.915 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听得愉快，是不是？</c>\n\nsrc-1257\n01:21:54.998 --> 01:21:57.000 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 爱珮呢？\n- 上学去了</c>\n\nsrc-1258\n01:21:57.084 --> 01:21:59.086 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上学？</c>\n\nsrc-1259\n01:21:59.169 --> 01:22:03.048 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她在纽约大学深造\n- 好啊</c>\n\nsrc-1260\n01:22:03.131 --> 01:22:06.552 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 等候吗？很快回来\n- 好</c>\n\nsrc-1261\n01:22:06.635 --> 01:22:10.222 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>随便坐，我要写求职信</c>\n\nsrc-1262\n01:22:10.305 --> 01:22:12.099 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>祝你好运</c>\n\nsrc-1263\n01:22:37.666 --> 01:22:39.084 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好</c>\n\nsrc-1264\n01:22:40.769 --> 01:22:42.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是奇云</c>\n\nsrc-1265\n01:22:44.006 --> 01:22:45.732 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯</c>\n\nsrc-1266\n01:22:46.383 --> 01:22:49.110 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在……等候爱珮</c>\n\nsrc-1267\n01:22:51.180 --> 01:22:54.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是她好些日子前提及的奇云？</c>\n\nsrc-1268\n01:22:54.850 --> 01:22:57.644 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是……除非她认识了一大堆奇云</c>\n\nsrc-1269\n01:22:57.728 --> 01:22:59.813 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇云，找你！</c>\n\nsrc-1270\n01:22:59.897 --> 01:23:03.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我应该是唯一和她同住的奇云</c>\n\nsrc-1271\n01:23:43.106 --> 01:23:45.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你知道自己要什么吗？</c>\n\nsrc-1272\n01:23:45.943 --> 01:23:47.778 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道</c>\n\nsrc-1273\n01:23:53.465 --> 01:23:55.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉？</c>\n\nsrc-1274\n01:23:55.285 --> 01:23:57.079 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯？</c>\n\nsrc-1275\n01:23:57.162 --> 01:23:59.331 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>吓</c>\n\nsrc-1276\n01:23:59.414 --> 01:24:01.208 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是你！</c>\n\nsrc-1277\n01:24:01.959 --> 01:24:03.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>容光焕发啊</c>\n\nsrc-1278\n01:24:04.545 --> 01:24:07.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>信不信由你，我一直想找你</c>\n\nsrc-1279\n01:24:09.258 --> 01:24:11.885 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我有了\n- 什么？</c>\n\nsrc-1280\n01:24:11.969 --> 01:24:13.345 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>出乎意料吧？</c>\n\nsrc-1281\n01:24:13.428 --> 01:24:16.014 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>坐啊，恭喜恭喜</c>\n\nsrc-1282\n01:24:16.098 --> 01:24:17.224 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谁是幸运儿？</c>\n\nsrc-1283\n01:24:17.307 --> 01:24:19.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>森诺禾斯</c>\n\nsrc-1284\n01:24:19.101 --> 01:24:21.186 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但他已经出局</c>\n\nsrc-1285\n01:24:21.270 --> 01:24:23.272 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>配不起你？</c>\n\nsrc-1286\n01:24:23.355 --> 01:24:28.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我用不着男人，从来用不着</c>\n\nsrc-1287\n01:24:28.652 --> 01:24:30.946 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是最惬意的一个</c>\n\nsrc-1288\n01:24:31.029 --> 01:24:35.117 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我本来打算跟定你，不过……</c>\n\nsrc-1289\n01:24:35.200 --> 01:24:36.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我自作孽</c>\n\nsrc-1290\n01:24:36.577 --> 01:24:39.413 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你没有\n- 肯定有</c>\n\nsrc-1291\n01:24:39.969 --> 01:24:41.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听着</c>\n\nsrc-1292\n01:24:41.582 --> 01:24:45.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>星期日……我举行一个小酒会</c>\n\nsrc-1293\n01:24:46.336 --> 01:24:47.977 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想你来</c>\n\nsrc-1294\n01:24:49.089 --> 01:24:51.675 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>四点钟，不准推搪</c>\n\nsrc-1295\n01:24:52.885 --> 01:24:55.734 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>肯来吗？来吧</c>\n\nsrc-1296\n01:24:55.776 --> 01:24:57.778 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我看看抽不抽出空</c>\n\nsrc-1297\n01:24:57.861 --> 01:25:00.572 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我很想你来\n- 我会去</c>\n\nsrc-1298\n01:25:00.684 --> 01:25:02.811 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我伤过很多人的心</c>\n\nsrc-1299\n01:25:02.895 --> 01:25:06.690 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想逐个和解，估计刚巧……</c>\n\nsrc-1300\n01:25:06.773 --> 01:25:08.650 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>需要九个月</c>\n\nsrc-1301\n01:25:10.319 --> 01:25:12.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她飘然而去\n- 拜拜</c>\n\nsrc-1302\n01:25:14.740 --> 01:25:16.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>威廉 希斯</c>\n\nsrc-1303\n01:25:16.116 --> 01:25:18.590 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者不是好主意</c>\n\nsrc-1304\n01:25:19.244 --> 01:25:23.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为我讲这故事……这神秘爱情故事</c>\n\nsrc-1305\n01:25:24.291 --> 01:25:27.669 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 万一我不喜欢我妈呢？\n- 你会喜欢</c>\n\nsrc-1306\n01:25:27.753 --> 01:25:30.589 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你很快会知道……</c>\n\nsrc-1307\n01:25:30.672 --> 01:25:33.342 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是阿夏，你不是我爸……</c>\n\nsrc-1308\n01:25:33.425 --> 01:25:35.149 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>难怪要离婚</c>\n\nsrc-1309\n01:25:35.232 --> 01:25:38.514 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要着急，只是故事</c>\n\nsrc-1310\n01:25:40.057 --> 01:25:42.643 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而这个故事有个圆满结局</c>\n\nsrc-1311\n01:25:42.726 --> 01:25:45.187 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么可能有圆满结局？</c>\n\nsrc-1312\n01:25:45.270 --> 01:25:49.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>无论我妈是谁，你跟她就快离婚</c>\n\nsrc-1313\n01:25:50.651 --> 01:25:53.111 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有什么好开心的？</c>\n\nsrc-1314\n01:25:57.407 --> 01:25:59.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者不应该讲下去</c>\n\nsrc-1315\n01:25:59.243 --> 01:26:00.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不行！</c>\n\nsrc-1316\n01:26:03.705 --> 01:26:05.791 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么，先呷杯茶怎样？</c>\n\nsrc-1317\n01:26:06.375 --> 01:26:09.670 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要我讲，我就讲下去</c>\n\nsrc-1318\n01:26:09.753 --> 01:26:11.755 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好吗？\n- 好</c>\n\nsrc-1319\n01:26:18.136 --> 01:26:19.638 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爸</c>\n\nsrc-1320\n01:26:21.431 --> 01:26:26.478 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真不敢相信你以前抽烟、喝酒，还那么滥情</c>\n\nsrc-1321\n01:26:29.606 --> 01:26:31.441 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过我依然爱你</c>\n\nsrc-1322\n01:27:34.671 --> 01:27:35.964 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-1323\n01:27:36.048 --> 01:27:38.258 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>得</c>\n\nsrc-1324\n01:27:38.342 --> 01:27:41.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>先不要吃！坐好才吃</c>\n\nsrc-1325\n01:27:42.304 --> 01:27:43.764 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你心情不错</c>\n\nsrc-1326\n01:27:43.847 --> 01:27:47.851 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道故事中谁是我妈</c>\n\nsrc-1327\n01:27:47.935 --> 01:27:49.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真的？\n- 真的</c>\n\nsrc-1328\n01:27:50.896 --> 01:27:53.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谁？\n- 不告诉你</c>\n\nsrc-1329\n01:27:54.942 --> 01:27:57.236 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>上回说到威廉 希斯……</c>\n\nsrc-1330\n01:27:57.319 --> 01:28:00.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发现自己其实爱爱珮……</c>\n\nsrc-1331\n01:28:00.989 --> 01:28:03.200 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但爱珮爱上另一个人</c>\n\nsrc-1332\n01:28:03.283 --> 01:28:05.369 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实在想不到</c>\n\nsrc-1333\n01:28:06.370 --> 01:28:08.372 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>旧女友阿夏家里举行酒会……</c>\n\nsrc-1334\n01:28:08.455 --> 01:28:11.458 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>请他去，证实阿夏是我妈的话……</c>\n\nsrc-1335\n01:28:11.542 --> 01:28:15.462 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会跑去加拿大</c>\n\nsrc-1336\n01:28:15.546 --> 01:28:17.172 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真的会</c>\n\nsrc-1337\n01:28:24.930 --> 01:28:26.609 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去年去世</c>\n\nsrc-1338\n01:28:27.432 --> 01:28:30.060 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你听闻过？\n- 在《时报》看到</c>\n\nsrc-1339\n01:28:31.895 --> 01:28:34.314 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>心脏病，死在办公室内？</c>\n\nsrc-1340\n01:28:34.398 --> 01:28:38.485 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总以为他会走得夸张</c>\n\nsrc-1341\n01:28:38.569 --> 01:28:42.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他搞上校长千金，马上风</c>\n\nsrc-1342\n01:28:42.114 --> 01:28:43.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 搞错\n- 只是开玩笑</c>\n\nsrc-1343\n01:28:44.658 --> 01:28:50.330 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实，他死得孤独\n死了几小时，校工才发现</c>\n\nsrc-1344\n01:28:51.290 --> 01:28:53.750 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 喝酒吗？\n- 很遗憾</c>\n\nsrc-1345\n01:28:53.834 --> 01:28:56.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你必定惦挂他\n- 惦挂啊</c>\n\nsrc-1346\n01:28:57.588 --> 01:28:59.265 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>小小意思</c>\n\nsrc-1347\n01:29:03.385 --> 01:29:05.220 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很美</c>\n\nsrc-1348\n01:29:07.306 --> 01:29:08.900 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你也美</c>\n\nsrc-1349\n01:29:10.934 --> 01:29:12.853 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏</c>\n\nsrc-1350\n01:29:12.936 --> 01:29:14.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不要来这一套</c>\n\nsrc-1351\n01:29:14.771 --> 01:29:17.909 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知你会说几句贴心话</c>\n\nsrc-1352\n01:29:17.992 --> 01:29:21.195 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>令我听得飘飘然</c>\n\nsrc-1353\n01:29:21.278 --> 01:29:24.448 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>随后怎样发展，你我预料得到</c>\n\nsrc-1354\n01:29:24.531 --> 01:29:26.742 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不可旧情复炽？\n- 只会难过收场</c>\n\nsrc-1355\n01:29:26.825 --> 01:29:30.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我真的没有空去伤心</c>\n\nsrc-1356\n01:29:31.330 --> 01:29:34.633 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可免则免，好不好？</c>\n\nsrc-1357\n01:29:36.301 --> 01:29:37.845 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有理</c>\n\nsrc-1358\n01:29:38.545 --> 01:29:40.472 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以做朋友吗？</c>\n\nsrc-1359\n01:29:41.924 --> 01:29:44.426 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 一言为定？\n- 得</c>\n\nsrc-1360\n01:29:47.638 --> 01:29:49.389 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样吧……</c>\n\nsrc-1361\n01:29:51.683 --> 01:29:54.102 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有个人我想你见见</c>\n\nsrc-1362\n01:29:55.187 --> 01:29:57.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟我来</c>\n\nsrc-1363\n01:29:57.698 --> 01:29:59.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我旧相好</c>\n\nsrc-1364\n01:29:59.149 --> 01:30:03.362 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们会一见如故</c>\n\nsrc-1365\n01:30:07.166 --> 01:30:08.792 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美莉</c>\n\nsrc-1366\n01:30:11.036 --> 01:30:13.163 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我去插花</c>\n\nsrc-1367\n01:30:16.667 --> 01:30:18.377 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好……</c>\n\nsrc-1368\n01:30:19.802 --> 01:30:21.512 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好气色</c>\n\nsrc-1369\n01:30:22.506 --> 01:30:25.676 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 为什么来纽约？\n- 我住在纽约</c>\n\nsrc-1370\n01:30:25.759 --> 01:30:29.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>替市区教育部办事</c>\n\nsrc-1371\n01:30:29.304 --> 01:30:31.731 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我打过电话给你\n- 我知</c>\n\nsrc-1372\n01:30:31.772 --> 01:30:34.351 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我想覆你\n- 骗人</c>\n\nsrc-1373\n01:30:35.394 --> 01:30:36.854 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我遗失了你电话\n- 不消说</c>\n\nsrc-1374\n01:30:36.937 --> 01:30:39.322 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真的，这样吧</c>\n\nsrc-1375\n01:30:39.405 --> 01:30:41.275 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你现在给号码我</c>\n\nsrc-1376\n01:30:41.358 --> 01:30:45.320 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我储入手机，那就万无一失</c>\n\nsrc-1377\n01:30:46.905 --> 01:30:52.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我号码是212……664-7665</c>\n\nsrc-1378\n01:30:52.286 --> 01:30:55.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在储入，不会再遗失</c>\n\nsrc-1379\n01:30:58.333 --> 01:31:00.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 接听吧\n- 不好意思</c>\n\nsrc-1380\n01:31:00.510 --> 01:31:02.129 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是威廉呀</c>\n\nsrc-1381\n01:31:03.380 --> 01:31:06.098 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>遗失你电话号码，很对不起</c>\n\nsrc-1382\n01:31:07.384 --> 01:31:11.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们当初结婚的话……</c>\n\nsrc-1383\n01:31:11.138 --> 01:31:13.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知会怎样？</c>\n\nsrc-1384\n01:31:16.435 --> 01:31:18.478 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发生了什么事？</c>\n\nsrc-1385\n01:31:18.562 --> 01:31:20.487 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你跟我室友上床</c>\n\nsrc-1386\n01:31:21.732 --> 01:31:23.066 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起</c>\n\nsrc-1387\n01:31:23.150 --> 01:31:25.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>原因是我的计划</c>\n\nsrc-1388\n01:31:25.986 --> 01:31:27.738 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对，那计划</c>\n\nsrc-1389\n01:31:27.821 --> 01:31:28.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你自己说过</c>\n\nsrc-1390\n01:31:28.989 --> 01:31:34.286 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实，我怕你，怕你的梦想</c>\n\nsrc-1391\n01:31:35.787 --> 01:31:38.790 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但分手后，我觉得很迷茫</c>\n\nsrc-1392\n01:31:39.958 --> 01:31:44.880 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我现在还是很迷茫，尤其在感情方面</c>\n\nsrc-1393\n01:31:48.217 --> 01:31:50.719 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我……我也是</c>\n\nsrc-1394\n01:31:57.100 --> 01:31:59.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有没有考虑过……</c>\n\nsrc-1395\n01:32:00.479 --> 01:32:03.941 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们或者……需要再订计划</c>\n\nsrc-1396\n01:32:04.525 --> 01:32:07.611 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等一等！停播！回带</c>\n\nsrc-1397\n01:32:09.029 --> 01:32:11.949 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>停播，现在向前……慢慢来</c>\n\nsrc-1398\n01:32:12.616 --> 01:32:14.117 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>接近了</c>\n\nsrc-1399\n01:32:14.201 --> 01:32:15.911 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就是那处！</c>\n\nsrc-1400\n01:32:15.994 --> 01:32:18.372 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>果然被我猜中</c>\n\nsrc-1401\n01:32:18.455 --> 01:32:20.165 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我难过时</c>\n\nsrc-1402\n01:32:20.249 --> 01:32:23.007 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>妈妈一定会摸摸我的头发……</c>\n\nsrc-1403\n01:32:23.090 --> 01:32:25.879 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>鼓励我，让我好受些</c>\n\nsrc-1404\n01:32:25.963 --> 01:32:28.382 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她听起来是个好妈妈\n- 她就是个好妈妈</c>\n\nsrc-1405\n01:32:28.465 --> 01:32:34.935 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么你绝对肯定……\n艾美莉就是那个正在……</c>\n\nsrc-1406\n01:32:35.347 --> 01:32:37.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>走来的女人</c>\n\nsrc-1407\n01:32:38.976 --> 01:32:40.727 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>绝对肯定</c>\n\nsrc-1408\n01:32:40.811 --> 01:32:42.443 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是不是？</c>\n\nsrc-1409\n01:32:44.064 --> 01:32:46.316 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>妈！</c>\n\nsrc-1410\n01:32:49.950 --> 01:32:51.280 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很高兴是你</c>\n\nsrc-1411\n01:32:51.363 --> 01:32:54.157 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 还会是谁？\n- 没有人</c>\n\nsrc-1412\n01:32:54.908 --> 01:32:57.536 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 早上好，威廉\n- 莎拉</c>\n\nsrc-1413\n01:32:58.412 --> 01:33:00.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爸陪我们去动物园好吗？</c>\n\nsrc-1414\n01:33:00.956 --> 01:33:03.083 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爸想去的话</c>\n\nsrc-1415\n01:33:04.751 --> 01:33:07.588 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢去，我们走</c>\n\nsrc-1416\n01:33:09.339 --> 01:33:13.427 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>妈，我们学校有性教育</c>\n\nsrc-1417\n01:33:13.510 --> 01:33:16.555 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是吗？\n- 是</c>\n\nsrc-1418\n01:33:28.738 --> 01:33:30.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢企鹅</c>\n\nsrc-1419\n01:33:31.195 --> 01:33:32.446 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也喜欢</c>\n\nsrc-1420\n01:33:32.529 --> 01:33:34.285 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也喜欢</c>\n\nsrc-1421\n01:33:44.082 --> 01:33:46.835 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>企鹅夫妻结合，一生一世</c>\n\nsrc-1422\n01:33:46.919 --> 01:33:51.507 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有时分开</c>\n\nsrc-1423\n01:33:51.590 --> 01:33:53.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为要搬屋</c>\n\nsrc-1424\n01:33:53.091 --> 01:33:54.930 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是候鸟</c>\n\nsrc-1425\n01:33:55.385 --> 01:33:59.932 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>分隔几年，但依然会团聚</c>\n\nsrc-1426\n01:34:04.394 --> 01:34:08.777 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>企鹅团聚，会怎样做？</c>\n\nsrc-1427\n01:34:09.900 --> 01:34:11.735 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>仰起头……</c>\n\nsrc-1428\n01:34:11.818 --> 01:34:15.072 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拍拍双翼，放声唱歌</c>\n\nsrc-1429\n01:35:00.659 --> 01:35:03.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>宝宝，我们走！</c>\n\nsrc-1430\n01:35:07.583 --> 01:35:11.172 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天玩得好开心，星期三再见</c>\n\nsrc-1431\n01:35:15.174 --> 01:35:16.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拜拜</c>\n\nsrc-1432\n01:35:19.722 --> 01:35:21.307 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爸！</c>\n\nsrc-1433\n01:35:28.228 --> 01:35:31.148 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 谢谢你讲这个故事\n- 不客气</c>\n\nsrc-1434\n01:35:32.693 --> 01:35:36.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我漏讲了那个圆满结局\n- 是什么？</c>\n\nsrc-1435\n01:35:37.865 --> 01:35:39.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是你</c>\n\nsrc-1436\n01:35:49.625 --> 01:35:52.002 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我疼你\n- 我也疼你</c>\n\nsrc-1437\n01:35:52.085 --> 01:35:55.297 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去妈妈处吧</c>\n\nadd-release-donor-1578\n01:35:57.508 --> 01:35:58.759 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没事吧？</c>\n\nadd-release-donor-1579\n01:35:58.842 --> 01:36:00.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\nsrc-1438\n01:36:18.487 --> 01:36:20.948 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>总统先生！</c>\n\nsrc-1439\n01:36:21.031 --> 01:36:24.034 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是威廉 希斯，92年助选！</c>\n\nsrc-1440\n01:36:38.424 --> 01:36:40.176 align:middle line:85%,start position:50%,middle\n离婚申请书\n\nsrc-1441\n01:37:49.203 --> 01:37:52.247 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>国际特赦组织</c>\n\nsrc-1442\n01:38:04.635 --> 01:38:07.179 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>查查他们有没有法律代表</c>\n\nsrc-1443\n01:38:17.356 --> 01:38:18.398 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是一份好工</c>\n\nsrc-1444\n01:38:18.482 --> 01:38:19.441 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\nsrc-1445\n01:38:19.525 --> 01:38:21.068 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 依然抽烟？\n- 戒了</c>\n\nsrc-1446\n01:38:21.151 --> 01:38:24.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我也戒了，住哪里？\n- 布鲁克林</c>\n\nsrc-1447\n01:38:24.736 --> 01:38:26.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>依然是潮流先锋</c>\n\nsrc-1448\n01:38:26.697 --> 01:38:29.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 在和谁约会吗？\n- 没有，你呢？</c>\n\nsrc-1449\n01:38:30.494 --> 01:38:32.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我离了婚</c>\n\nsrc-1450\n01:38:32.161 --> 01:38:34.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我听闻过，很遗憾</c>\n\nsrc-1451\n01:38:34.581 --> 01:38:38.041 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你总是说婚姻是名过其实</c>\n\nsrc-1452\n01:38:38.083 --> 01:38:41.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你总是听不入耳，婚戒买完又买</c>\n\nsrc-1453\n01:38:41.505 --> 01:38:44.715 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你同奇云……\n- 不要提奇云</c>\n\nsrc-1454\n01:38:45.843 --> 01:38:48.719 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>同奇云有点不合拍</c>\n\nsrc-1455\n01:38:49.761 --> 01:38:54.017 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>奇怪，总觉得……不太对劲</c>\n\nsrc-1456\n01:38:56.728 --> 01:38:59.481 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 见到你真好\n- 我也是</c>\n\nsrc-1457\n01:39:02.566 --> 01:39:04.778 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有件东西给你</c>\n\nsrc-1458\n01:39:46.820 --> 01:39:48.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>非常谢谢</c>\n\nsrc-1459\n01:39:49.990 --> 01:39:52.782 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎样找到？哪里找到？</c>\n\nsrc-1460\n01:39:54.578 --> 01:39:57.206 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也不知怎样说好</c>\n\nsrc-1461\n01:39:59.541 --> 01:40:01.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很难出口</c>\n\nsrc-1462\n01:40:02.419 --> 01:40:04.254 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我找到相当久</c>\n\nsrc-1463\n01:40:05.422 --> 01:40:06.963 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>多久？</c>\n\nsrc-1464\n01:40:07.674 --> 01:40:09.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>几年</c>\n\nsrc-1465\n01:40:10.010 --> 01:40:11.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很多年</c>\n\nsrc-1466\n01:40:12.300 --> 01:40:14.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我本来……</c>\n\nsrc-1467\n01:40:14.389 --> 01:40:16.433 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>本来打算给你，我想给你</c>\n\nsrc-1468\n01:40:16.517 --> 01:40:21.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是送不出手，也不明白</c>\n\nsrc-1469\n01:40:22.814 --> 01:40:26.860 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我送过去你家，看到奇云……</c>\n\nsrc-1470\n01:40:26.944 --> 01:40:30.572 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没有借口，对不起</c>\n\nsrc-1471\n01:40:31.532 --> 01:40:33.617 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我难辞其咎</c>\n\nsrc-1472\n01:40:37.621 --> 01:40:40.374 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我认为你应该走\n- 爱珮</c>\n\nsrc-1473\n01:40:41.792 --> 01:40:43.669 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我认为你应该走</c>\n\nsrc-1474\n01:40:57.846 --> 01:41:01.270 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样久以来，你没有给她？</c>\n\nsrc-1475\n01:41:01.353 --> 01:41:03.272 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对\n- 是她爸送的礼物</c>\n\nsrc-1476\n01:41:03.355 --> 01:41:05.566 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知</c>\n\nsrc-1477\n01:41:05.649 --> 01:41:07.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后你就走？</c>\n\nsrc-1478\n01:41:08.694 --> 01:41:10.237 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对</c>\n\nsrc-1479\n01:41:11.530 --> 01:41:14.741 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所有人物都改名换姓，除了她</c>\n\nsrc-1480\n01:41:14.825 --> 01:41:15.909 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么意思？</c>\n\nsrc-1481\n01:41:15.993 --> 01:41:18.871 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>故事中，妈变成艾美莉</c>\n\nsrc-1482\n01:41:18.954 --> 01:41:22.666 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>阿夏是写杂志稿的娜塔莎</c>\n\nsrc-1483\n01:41:22.749 --> 01:41:25.335 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但你没有改爱珮，为什么？</c>\n\nsrc-1484\n01:41:28.463 --> 01:41:32.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你干嘛非要对这些事打破砂锅问到底？</c>\n\nsrc-1485\n01:41:32.759 --> 01:41:34.924 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我希望你快乐</c>\n\nsrc-1486\n01:41:35.216 --> 01:41:37.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要明白……</c>\n\nsrc-1487\n01:41:37.806 --> 01:41:39.474 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我快乐</c>\n\nsrc-1488\n01:41:40.184 --> 01:41:42.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>信我吧，你不快乐</c>\n\nsrc-1489\n01:41:56.783 --> 01:41:58.405 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>穿上外衣</c>\n\nsrc-1490\n01:42:03.790 --> 01:42:05.292 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>出租车！</c>\n\nsrc-1491\n01:42:12.090 --> 01:42:13.842 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>同奇云有点不合拍</c>\n\nsrc-1492\n01:42:13.926 --> 01:42:16.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或者同你合拍</c>\n\nsrc-1493\n01:42:16.678 --> 01:42:19.431 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那是好事\n- 有可能</c>\n\nsrc-1494\n01:42:20.343 --> 01:42:21.970 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有可能</c>\n\nsrc-1495\n01:42:23.227 --> 01:42:27.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每年有35人伤心过度……</c>\n\nsrc-1496\n01:42:27.105 --> 01:42:29.566 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跳布鲁克林桥</c>\n\nsrc-1497\n01:42:30.234 --> 01:42:31.902 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会记住</c>\n\nsrc-1498\n01:42:49.878 --> 01:42:52.840 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好</c>\n\nsrc-1499\n01:42:52.923 --> 01:42:54.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是威廉呀</c>\n\nsrc-1500\n01:42:56.462 --> 01:42:58.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱珮</c>\n\nsrc-1501\n01:43:03.976 --> 01:43:05.811 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你来做什么？</c>\n\nsrc-1502\n01:43:08.272 --> 01:43:10.065 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>告诉她吧</c>\n\nsrc-1503\n01:43:11.066 --> 01:43:12.568 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是谁？</c>\n\nsrc-1504\n01:43:12.651 --> 01:43:15.737 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我女儿玛雅</c>\n\nsrc-1505\n01:43:15.821 --> 01:43:18.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你这是耍赖……带女儿来</c>\n\nsrc-1506\n01:43:18.198 --> 01:43:20.027 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我怎办？</c>\n\nsrc-1507\n01:43:21.451 --> 01:43:23.453 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以开门</c>\n\nsrc-1508\n01:43:26.373 --> 01:43:29.042 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她不肯开门</c>\n\nsrc-1509\n01:43:30.961 --> 01:43:32.588 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你错了</c>\n\nsrc-1510\n01:43:33.797 --> 01:43:35.132 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们走</c>\n\nsrc-1511\n01:43:35.215 --> 01:43:38.802 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>多等一等，她会开</c>\n\nsrc-1512\n01:43:38.886 --> 01:43:40.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样吧</c>\n\nsrc-1513\n01:43:41.054 --> 01:43:43.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我数到30</c>\n\nsrc-1514\n01:43:43.223 --> 01:43:45.225 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不开门，我们回家</c>\n\nsrc-1515\n01:43:45.309 --> 01:43:47.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>以后绝口不提</c>\n\nsrc-1516\n01:43:47.311 --> 01:43:48.846 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>同意？</c>\n\nsrc-1517\n01:43:50.063 --> 01:43:51.516 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>准备</c>\n\nsrc-1518\n01:43:51.815 --> 01:43:56.278 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>1……2……3……</c>\n\nsrc-1519\n01:43:56.361 --> 01:44:00.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>4……5……6……</c>\n\nsrc-1520\n01:44:01.491 --> 01:44:06.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>14……15……16……17……</c>\n\nsrc-1521\n01:44:06.663 --> 01:44:09.583 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你见到她，像对我一样讲那故事</c>\n\nsrc-1522\n01:44:09.666 --> 01:44:12.002 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她会明白\n- 明白什么？</c>\n\nsrc-1523\n01:44:12.085 --> 01:44:14.288 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也解释不出来，总之明白</c>\n\nsrc-1524\n01:44:14.963 --> 01:44:19.801 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>25……26……27……</c>\n\nsrc-1525\n01:44:22.346 --> 01:44:24.056 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>29……</c>\n\nsrc-1526\n01:44:26.141 --> 01:44:28.602 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>29又4份之1</c>\n\nsrc-1527\n01:44:28.685 --> 01:44:31.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>29又2份之1</c>\n\nsrc-1528\n01:44:33.148 --> 01:44:35.484 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>29又4份之3</c>\n\nsrc-1529\n01:44:36.811 --> 01:44:38.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟着是什么</c>\n\nsrc-1530\n01:44:41.156 --> 01:44:42.732 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>应该走了</c>\n\nsrc-1531\n01:44:45.410 --> 01:44:47.788 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不应该是这样</c>\n\nsrc-1532\n01:44:48.446 --> 01:44:53.210 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她应该从对讲机听到……</c>\n\nsrc-1533\n01:44:53.293 --> 01:44:54.837 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会开门，或者会跑下来……</c>\n\nsrc-1534\n01:44:54.920 --> 01:44:56.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么故事？</c>\n\nsrc-1535\n01:45:00.133 --> 01:45:01.793 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么故事？</c>\n\nsrc-1536\n01:45:13.355 --> 01:45:15.858 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我收藏着那本书……</c>\n\nsrc-1537\n01:45:17.276 --> 01:45:20.863 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为那是我关于你唯一留下的东西</c>\n\nsrc-1538\n01:45:41.592 --> 01:45:45.554 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你必定是玛雅\n- 你必定是爱珮</c>\n\nsrc-1539\n01:45:50.058 --> 01:45:52.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么，现在怎办？</c>\n\nsrc-1540\n01:45:52.311 --> 01:45:55.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>请我们进去，我们给你讲故事</c>\n\nsrc-1541\n01:45:56.690 --> 01:45:57.941 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n";
